class WorkspaceRevisionConflict(Exception):
    """Raised when a workspace command targets a stale row version."""

    def __init__(self, current_version: int):
        self.current_version = int(current_version)
        super().__init__(
            f"workspace revision conflict; current version is {self.current_version}"
        )


class WorkspaceOperationConflict(Exception):
    """Raised when an actor reuses one operation ID for different input."""

    def __init__(self, operation_id: str):
        self.operation_id = str(operation_id)
        super().__init__("operation_id was already used for a different workspace request")


class WorkspaceSubstrateUnavailable(Exception):
    """Raised until the explicit workspace catalog bootstrap has run."""

    pass


class WorkspaceCatalogFingerprintConflict(Exception):
    """Raised when an offline command loses its exact catalog snapshot fence."""

    pass


class WorkspaceOutboxLeaseConflict(Exception):
    """Raised for an absent, expired, wrong-worker, or stale delivery lease."""

    pass


class WorkspacePageSourceSuperseded(Exception):
    """Raised when a maintenance cursor names a non-active binding generation."""

    pass


class WorkspacePageProjectionAmbiguous(ValueError):
    """Raised when one sanitized locator collides with another page."""

    pass


class WorkspaceHealingLeaseConflict(Exception):
    """Raised for a stale run version, fence, worker, token, or lease."""

    pass


class WorkspaceHealingSourceFenceConflict(Exception):
    """Raised when one locator-apply pass would mix legacy source snapshots."""

    pass


class WorkspacePageTreeSourceFenceConflict(Exception):
    """Raised when a page-tree source snapshot changes before catalog commit."""

    pass


class WorkspacePageLifecycleLeaseConflict(Exception):
    """Raised for a stale command version, fence, worker, token, or lease."""

    pass


class WorkspacePageLifecycleSourceConflict(Exception):
    """Raised when a source receipt changes before it is durably recorded."""

    pass


@dataclass(frozen=True)
class LegacyPageSourceProof:
    """Immutable descriptor produced by an authorized legacy page read."""

    actor_subject_id: str
    owner_subject_id: str
    page_id: str
    revision: int
    updated_at: int
    content_sha256: str

    def descriptor(self) -> dict[str, Any]:
        return {
            "actor_subject_id": self.actor_subject_id,
            "owner_subject_id": self.owner_subject_id,
            "page_id": self.page_id,
            "revision": self.revision,
            "updated_at": self.updated_at,
            "content_sha256": self.content_sha256,
        }


@dataclass(frozen=True)
class LegacyFileSourceLocator:
    """Secret-free locator for one legacy file row."""

    source_file_id: str

    def descriptor(self) -> dict[str, Any]:
        return {"source_file_id": self.source_file_id}


@dataclass(frozen=True)
class LegacyPublicSourceLocator:
    """One public locator containing only a one-way token digest."""

    token_sha256: str
    allow_duplicate: bool

    def descriptor(self) -> dict[str, Any]:
        return {
            "token_sha256": self.token_sha256,
            "allow_duplicate": self.allow_duplicate,
        }


@dataclass(frozen=True)
class LegacyPageLocatorProjection:
    """Immutable, sanitized file/public projection for one page generation."""

    actor_subject_id: str
    owner_subject_id: str
    page_id: str
    binding_version: int
    file_sources: tuple[LegacyFileSourceLocator, ...] = ()
    public_sources: tuple[LegacyPublicSourceLocator, ...] = ()

    def descriptor(self) -> dict[str, Any]:
        return {
            "actor_subject_id": self.actor_subject_id,
            "owner_subject_id": self.owner_subject_id,
            "page_id": self.page_id,
            "binding_version": self.binding_version,
            "file_sources": [item.descriptor() for item in self.file_sources],
            "public_sources": [item.descriptor() for item in self.public_sources],
        }


