@dataclass(frozen=True)
class LegacyPageHealingCandidate:
    """Bounded, secret-free legacy page state proposed for atomic healing."""

    workspace_id: str
    workspace_version: int
    owner_subject_id: str
    page_id: str
    binding_version: int
    binding_state: str
    bound_by_subject_id: str
    proof_actor_subject_id: str
    source_epoch: int
    full_sweep_generation: int
    source_device: int
    source_inode: int
    source_link_count: int
    change_generation: int
    change_mask: int
    source_exists: bool
    source_active: bool
    source_proof: LegacyPageSourceProof | None = None
    file_sources: tuple[LegacyFileSourceLocator, ...] = ()
    public_sources: tuple[LegacyPublicSourceLocator, ...] = ()

    def source_fence(self) -> WorkspaceHealingSourceFence:
        return WorkspaceHealingSourceFence(
            source_epoch=self.source_epoch,
            full_sweep_generation=self.full_sweep_generation,
            source_device=self.source_device,
            source_inode=self.source_inode,
            source_link_count=self.source_link_count,
        )

    def descriptor(self) -> dict[str, Any]:
        return {
            "workspace_id": self.workspace_id,
            "workspace_version": self.workspace_version,
            "owner_subject_id": self.owner_subject_id,
            "page_id": self.page_id,
            "binding_version": self.binding_version,
            "binding_state": self.binding_state,
            "bound_by_subject_id": self.bound_by_subject_id,
            "proof_actor_subject_id": self.proof_actor_subject_id,
            "source_fence": self.source_fence().descriptor(),
            "change_generation": self.change_generation,
            "change_mask": self.change_mask,
            "source_exists": self.source_exists,
            "source_active": self.source_active,
            "source_proof": (
                self.source_proof.descriptor() if self.source_proof is not None else None
            ),
            "file_sources": [item.descriptor() for item in self.file_sources],
            "public_sources": [item.descriptor() for item in self.public_sources],
        }


@dataclass(frozen=True)
class LegacyPageQuarantineCandidate:
    """Secret-free, source-fenced evidence for a permanent healing refusal.

    These candidates deliberately carry no page proof, attachment metadata,
    filesystem path, or public token.  They let the catalog remove a stale
    locator atomically instead of merely counting an error while leaving the
    old projection active.
    """

    workspace_id: str
    workspace_version: int
    owner_subject_id: str
    page_id: str
    binding_version: int
    binding_state: str
    bound_by_subject_id: str
    proof_actor_subject_id: str
    source_epoch: int
    full_sweep_generation: int
    source_device: int
    source_inode: int
    source_link_count: int
    change_generation: int
    change_mask: int
    source_exists: bool
    source_active: bool
    quarantine_reason: str

    def source_fence(self) -> WorkspaceHealingSourceFence:
        return WorkspaceHealingSourceFence(
            source_epoch=self.source_epoch,
            full_sweep_generation=self.full_sweep_generation,
            source_device=self.source_device,
            source_inode=self.source_inode,
            source_link_count=self.source_link_count,
        )

    def descriptor(self) -> dict[str, Any]:
        return {
            "workspace_id": self.workspace_id,
            "workspace_version": self.workspace_version,
            "owner_subject_id": self.owner_subject_id,
            "page_id": self.page_id,
            "binding_version": self.binding_version,
            "binding_state": self.binding_state,
            "bound_by_subject_id": self.bound_by_subject_id,
            "proof_actor_subject_id": self.proof_actor_subject_id,
            "source_fence": self.source_fence().descriptor(),
            "change_generation": self.change_generation,
            "change_mask": self.change_mask,
            "source_exists": self.source_exists,
            "source_active": self.source_active,
            "quarantine_reason": self.quarantine_reason,
        }


