def _replace_schema_segment(
    source: str, start_marker: str, end_marker: str, replacement: str
) -> str:
    start = source.find(start_marker)
    end = source.find(end_marker, start + len(start_marker))
    if start < 0 or end < 0:
        raise RuntimeError("workspace 1317 schema reconstruction drifted")
    return source[:start] + replacement + source[end:]


