def _page_tree_snapshot_sha256(
    *,
    workspace_id: str,
    expected_tree_version: int,
    expected_tree_state_version: int,
    source_fence_set_sha256: str,
    nodes: tuple[WorkspacePageTreeNodeCandidate, ...],
) -> str:
    payload = {
        "domain": PAGE_TREE_SNAPSHOT_DOMAIN,
        "workspace_id": workspace_id,
        "expected_tree_version": expected_tree_version,
        "expected_tree_state_version": expected_tree_state_version,
        "source_fence_set_sha256": source_fence_set_sha256,
        "nodes": [item.descriptor() for item in nodes],
    }
    return "sha256:" + hashlib.sha256(
        _canonical_json(payload).encode("utf-8")
    ).hexdigest()


def _normalize_page_tree_snapshot(
    value: WorkspacePageTreeSnapshot,
) -> WorkspacePageTreeSnapshot:
    """Validate and canonicalize one bounded, parent-first active tree."""
    if not isinstance(value, WorkspacePageTreeSnapshot):
        raise ValueError("WorkspacePageTreeSnapshot required")
    workspace_id = _identifier(
        value.workspace_id, prefix="ws", field="page tree workspace_id"
    )
    if value.workspace_id != workspace_id:
        raise ValueError("page tree workspace_id must be canonical")
    expected_tree_version = _bounded_integer(
        value.expected_tree_version,
        field="expected_tree_version",
        minimum=0,
        maximum=MAX_HEALING_SEQUENCE_VALUE - 1,
    )
    expected_tree_state_version = _bounded_integer(
        value.expected_tree_state_version,
        field="expected_tree_state_version",
        minimum=1,
        maximum=MAX_HEALING_SEQUENCE_VALUE - 1,
    )
    if not isinstance(value.source_fences, tuple):
        raise ValueError("page tree source_fences must be a tuple")
    normalized_fences: list[WorkspacePageTreeSourceFence] = []
    seen_owners: set[str] = set()
    for item in value.source_fences:
        if not isinstance(item, WorkspacePageTreeSourceFence):
            raise ValueError("WorkspacePageTreeSourceFence required")
        owner = _subject(
            item.source_owner_subject_id,
            field="page tree source_owner_subject_id",
        )
        if item.source_owner_subject_id != owner or owner in seen_owners:
            raise ValueError("page tree source fences must have unique canonical owners")
        seen_owners.add(owner)
        normalized_fences.append(
            WorkspacePageTreeSourceFence(
                source_owner_subject_id=owner,
                source_epoch=_bounded_integer(
                    item.source_epoch,
                    field="page tree source_epoch",
                    minimum=1,
                    maximum=MAX_HEALING_SEQUENCE_VALUE,
                ),
                full_sweep_generation=_bounded_integer(
                    item.full_sweep_generation,
                    field="page tree full_sweep_generation",
                    minimum=1,
                    maximum=MAX_HEALING_SEQUENCE_VALUE,
                ),
                source_device=sqlite_source_identity(item.source_device),
                source_inode=sqlite_source_identity(item.source_inode),
                source_link_count=_bounded_integer(
                    item.source_link_count,
                    field="page tree source_link_count",
                    minimum=1,
                    maximum=65535,
                ),
            )
        )
    normalized_fences_tuple = tuple(
        sorted(normalized_fences, key=lambda item: item.source_owner_subject_id)
    )
    if tuple(value.source_fences) != normalized_fences_tuple:
        raise ValueError("page tree source fences must be canonical and sorted")
    fence_digest = _page_tree_source_fence_set_sha256(normalized_fences_tuple)
    if _sha256_digest(
        value.source_fence_set_sha256, field="page tree source fence set"
    ) != fence_digest:
        raise ValueError("page tree source fence set digest mismatch")

    if not isinstance(value.nodes, tuple):
        raise ValueError("page tree nodes must be a tuple")
    if len(value.nodes) > MAX_PAGE_TREE_SYNCHRONOUS_SUBTREE_NODES:
        raise ValueError("page tree snapshot exceeds the synchronous node bound")
    normalized_nodes: list[WorkspacePageTreeNodeCandidate] = []
    seen_nodes: set[tuple[str, str]] = set()
    for item in value.nodes:
        if not isinstance(item, WorkspacePageTreeNodeCandidate):
            raise ValueError("WorkspacePageTreeNodeCandidate required")
        item_workspace = _identifier(
            item.workspace_id, prefix="ws", field="page tree node workspace_id"
        )
        owner = _subject(
            item.source_owner_subject_id,
            field="page tree node source_owner_subject_id",
        )
        page_id = str(item.source_page_id or "")
        if (
            item_workspace != workspace_id
            or item.workspace_id != item_workspace
            or item.source_owner_subject_id != owner
            or not page_id
            or page_id != page_id.strip()
            or len(page_id) > 160
        ):
            raise ValueError("page tree node identity is invalid")
        key = (owner, page_id)
        if key in seen_nodes:
            raise ValueError("page tree node identity is duplicated")
        seen_nodes.add(key)
        binding_version = _bounded_integer(
            item.binding_version,
            field="page tree binding_version",
            minimum=1,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        )
        incarnation_id = str(item.source_incarnation_id or "")
        if not re.fullmatch(r"inc_[0-9a-f]{32}", incarnation_id):
            raise ValueError("valid page tree source incarnation required")
        incarnation_generation = _bounded_integer(
            item.source_incarnation_generation,
            field="page tree source_incarnation_generation",
            minimum=1,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        )
        change_generation = _bounded_integer(
            item.source_change_generation,
            field="page tree source_change_generation",
            minimum=1,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        )
        receipt_sha256 = _sha256_digest(
            item.source_receipt_sha256, field="page tree source receipt"
        )
        parent_owner = str(item.parent_source_owner_subject_id or "")
        parent_page = str(item.parent_source_page_id or "")
        if bool(parent_owner) != bool(parent_page):
            raise ValueError("page tree parent identity must be complete")
        if parent_owner:
            canonical_parent_owner = _subject(
                parent_owner, field="page tree parent source_owner_subject_id"
            )
            if canonical_parent_owner != owner or parent_owner != owner:
                raise ValueError("cross-owner page tree parentage is unsupported")
            if (
                not parent_page
                or parent_page != parent_page.strip()
                or len(parent_page) > 160
                or parent_page == page_id
            ):
                raise ValueError("page tree parent identity is invalid")
        sibling_ordinal = _bounded_integer(
            item.sibling_ordinal,
            field="page tree sibling_ordinal",
            minimum=1,
            maximum=MAX_PAGE_TREE_SIBLING_NODES,
        )
        depth = _bounded_integer(
            item.depth,
            field="page tree depth",
            minimum=0,
            maximum=MAX_PAGE_TREE_DEPTH,
        )
        if bool(parent_owner) is not (depth > 0):
            raise ValueError("page tree depth does not match its parent")
        expected_structure = _page_tree_node_structure_sha256(
            workspace_id=workspace_id,
            source_owner_subject_id=owner,
            source_page_id=page_id,
            binding_version=binding_version,
            source_incarnation_id=incarnation_id,
            source_incarnation_generation=incarnation_generation,
            source_change_generation=change_generation,
            source_receipt_sha256=receipt_sha256,
            parent_source_owner_subject_id=parent_owner,
            parent_source_page_id=parent_page,
            sibling_ordinal=sibling_ordinal,
            depth=depth,
        )
        if _sha256_digest(
            item.structure_sha256, field="page tree structure"
        ) != expected_structure:
            raise ValueError("page tree node structure digest mismatch")
        normalized_nodes.append(
            WorkspacePageTreeNodeCandidate(
                workspace_id=workspace_id,
                source_owner_subject_id=owner,
                source_page_id=page_id,
                binding_version=binding_version,
                source_incarnation_id=incarnation_id,
                source_incarnation_generation=incarnation_generation,
                source_change_generation=change_generation,
                source_receipt_sha256=receipt_sha256,
                parent_source_owner_subject_id=parent_owner,
                parent_source_page_id=parent_page,
                sibling_ordinal=sibling_ordinal,
                depth=depth,
                structure_sha256=expected_structure,
            )
        )

    canonical_nodes = tuple(
        sorted(
            normalized_nodes,
            key=lambda item: (
                item.depth,
                item.parent_source_owner_subject_id,
                item.parent_source_page_id,
                item.sibling_ordinal,
                item.source_owner_subject_id,
                item.source_page_id,
            ),
        )
    )
    if tuple(value.nodes) != canonical_nodes:
        raise ValueError("page tree nodes must be canonical and parent-first")
    nodes_by_key = {
        (item.source_owner_subject_id, item.source_page_id): item
        for item in canonical_nodes
    }
    sibling_scopes: dict[tuple[str, str], list[int]] = {}
    for item in canonical_nodes:
        if item.source_owner_subject_id not in seen_owners:
            raise ValueError("page tree node source fence is unavailable")
        if item.parent_source_owner_subject_id:
            parent = nodes_by_key.get(
                (
                    item.parent_source_owner_subject_id,
                    item.parent_source_page_id,
                )
            )
            if parent is None or parent.depth + 1 != item.depth:
                raise ValueError("page tree parent is unavailable or cyclic")
        scope = (
            item.parent_source_owner_subject_id,
            item.parent_source_page_id,
        )
        sibling_scopes.setdefault(scope, []).append(item.sibling_ordinal)
    for ordinals in sibling_scopes.values():
        if sorted(ordinals) != list(range(1, len(ordinals) + 1)):
            raise ValueError("page tree sibling ordinals must be dense")
    node_owners = {item.source_owner_subject_id for item in canonical_nodes}
    if node_owners != seen_owners:
        raise ValueError("page tree source fence owners do not match the nodes")

    snapshot_sha256 = _page_tree_snapshot_sha256(
        workspace_id=workspace_id,
        expected_tree_version=expected_tree_version,
        expected_tree_state_version=expected_tree_state_version,
        source_fence_set_sha256=fence_digest,
        nodes=canonical_nodes,
    )
    if _sha256_digest(
        value.snapshot_sha256, field="page tree snapshot"
    ) != snapshot_sha256:
        raise ValueError("page tree snapshot digest mismatch")
    return WorkspacePageTreeSnapshot(
        workspace_id=workspace_id,
        expected_tree_version=expected_tree_version,
        expected_tree_state_version=expected_tree_state_version,
        source_fences=normalized_fences_tuple,
        nodes=canonical_nodes,
        source_fence_set_sha256=fence_digest,
        snapshot_sha256=snapshot_sha256,
    )


def _normalize_owner_canonical_source_proof(
    value: LegacyPageSourceProof,
) -> LegacyPageSourceProof:
    """Normalize proof captured as the exact legacy owner, not the reviewer."""
    if not isinstance(value, LegacyPageSourceProof):
        raise ValueError("LegacyPageSourceProof required")
    actor = _subject(value.actor_subject_id, field="source_proof.actor_subject_id")
    owner = _subject(value.owner_subject_id, field="source_proof.owner_subject_id")
    if value.actor_subject_id != actor or value.owner_subject_id != owner:
        raise ValueError("source proof identity must be canonical")
    if actor != owner:
        raise PermissionError("rebind source proof must be owner-canonical")
    page_id = str(value.page_id or "")
    if not page_id or page_id != page_id.strip() or len(page_id) > 160:
        raise ValueError("valid source proof page_id required")
    revision = _bounded_integer(
        value.revision,
        field="source proof revision",
        minimum=1,
        maximum=MAX_HEALING_SEQUENCE_VALUE,
    )
    updated_at = _bounded_integer(
        value.updated_at,
        field="source proof updated_at",
        minimum=0,
        maximum=MAX_HEALING_TIMESTAMP,
    )
    content_sha256 = _sha256_digest(
        value.content_sha256, field="source proof content_sha256"
    )
    return LegacyPageSourceProof(
        actor_subject_id=owner,
        owner_subject_id=owner,
        page_id=page_id,
        revision=revision,
        updated_at=updated_at,
        content_sha256=content_sha256,
    )


def _assert_incarnation_lineage(
    con: sqlite3.Connection,
    evidence: LegacyPageIncarnationEvidence,
) -> None:
    """Reject a rolled-back or contradictory legacy-v2 source lineage.

    Equal counters are valid when an unchanged incarnation is reviewed for a
    later catalog binding generation.  A previously unseen incarnation nonce
    is a new page lifetime, so its page-local incarnation, epoch, sweep, and
    change generations must all strictly advance.  Source file identity is
    owner-shard identity and may only change through a future, separately
    audited source-rebase operation.
    """
    parameters = {
        "owner": evidence.owner_subject_id,
        "page": evidence.page_id,
        "incarnation_id": evidence.incarnation_id,
        "incarnation_generation": evidence.incarnation_generation,
        "source_epoch": evidence.source_epoch,
        "full_sweep_generation": evidence.full_sweep_generation,
        "source_device": evidence.source_device,
        "source_inode": evidence.source_inode,
        "source_link_count": evidence.source_link_count,
        "change_generation": evidence.change_generation,
        "change_mask": evidence.change_mask,
    }
    stale = con.execute(
        """
        SELECT 1
        WHERE EXISTS (
          SELECT 1 FROM workspace_page_source_incarnation_attestations existing
          WHERE existing.source_owner_subject_id=:owner
            AND (
              existing.source_device<>:source_device
              OR existing.source_inode<>:source_inode
              OR existing.source_link_count<>:source_link_count
            )
        )
        OR :source_epoch<COALESCE((
          SELECT MAX(existing.source_epoch)
          FROM workspace_page_source_incarnation_attestations existing
          WHERE existing.source_owner_subject_id=:owner
        ),:source_epoch)
        OR :full_sweep_generation<COALESCE((
          SELECT MAX(existing.full_sweep_generation)
          FROM workspace_page_source_incarnation_attestations existing
          WHERE existing.source_owner_subject_id=:owner
        ),:full_sweep_generation)
        OR EXISTS (
          SELECT 1 FROM workspace_page_source_incarnation_attestations existing
          WHERE existing.source_owner_subject_id=:owner
            AND existing.source_page_id=:page
            AND (
              existing.source_change_generation>:change_generation
              OR (existing.source_change_mask | :change_mask)<>:change_mask
              OR (
                existing.source_incarnation_id=:incarnation_id
                AND existing.source_incarnation_generation
                    <>:incarnation_generation
              )
              OR (
                existing.source_incarnation_generation
                    =:incarnation_generation
                AND existing.source_incarnation_id<>:incarnation_id
              )
              OR existing.source_incarnation_generation
                 >:incarnation_generation
            )
        )
        OR (
          EXISTS (
            SELECT 1 FROM workspace_page_source_incarnation_attestations existing
            WHERE existing.source_owner_subject_id=:owner
              AND existing.source_page_id=:page
          )
          AND NOT EXISTS (
            SELECT 1 FROM workspace_page_source_incarnation_attestations existing
            WHERE existing.source_owner_subject_id=:owner
              AND existing.source_page_id=:page
              AND existing.source_incarnation_id=:incarnation_id
          )
          AND (
            :incarnation_generation<=COALESCE((
              SELECT MAX(existing.source_incarnation_generation)
              FROM workspace_page_source_incarnation_attestations existing
              WHERE existing.source_owner_subject_id=:owner
                AND existing.source_page_id=:page
            ),0)
            OR :source_epoch<=COALESCE((
              SELECT MAX(existing.source_epoch)
              FROM workspace_page_source_incarnation_attestations existing
              WHERE existing.source_owner_subject_id=:owner
                AND existing.source_page_id=:page
            ),0)
            OR :full_sweep_generation<=COALESCE((
              SELECT MAX(existing.full_sweep_generation)
              FROM workspace_page_source_incarnation_attestations existing
              WHERE existing.source_owner_subject_id=:owner
                AND existing.source_page_id=:page
            ),0)
            OR :change_generation<=COALESCE((
              SELECT MAX(existing.source_change_generation)
              FROM workspace_page_source_incarnation_attestations existing
              WHERE existing.source_owner_subject_id=:owner
                AND existing.source_page_id=:page
            ),0)
          )
        )
        """,
        parameters,
    ).fetchone()
    if stale is not None:
        raise ValueError("source incarnation lineage is stale")


def _incarnation_attestation_payload(row: sqlite3.Row) -> dict[str, Any]:
    """Decode the exact secret-free audit/outbox payload for one attestation."""
    return {
        "workspace_id": str(row["workspace_id"]),
        "source_owner_subject_id": str(row["source_owner_subject_id"]),
        "source_page_id": str(row["source_page_id"]),
        "binding_version": int(row["binding_version"]),
        "source_incarnation_id": str(row["source_incarnation_id"]),
        "source_incarnation_generation": int(row["source_incarnation_generation"]),
        "source_incarnation_retired": bool(row["source_incarnation_retired"]),
        "source_epoch": int(row["source_epoch"]),
        "full_sweep_generation": int(row["full_sweep_generation"]),
        "source_device": int(row["source_device"]),
        "source_inode": int(row["source_inode"]),
        "source_link_count": int(row["source_link_count"]),
        "source_change_generation": int(row["source_change_generation"]),
        "source_change_mask": int(row["source_change_mask"]),
        "source_exists": bool(row["source_exists"]),
        "source_active": bool(row["source_active"]),
        "source_receipt_domain": str(row["source_receipt_domain"]),
        "source_receipt_sha256": str(row["source_receipt_sha256"]),
        "reviewed_by_subject_id": str(row["reviewed_by_subject_id"]),
        "review_operation_id": str(row["review_operation_id"]),
        "created_at": int(row["created_at"]),
    }


def _validate_incarnation_attestation_operation_result(
    result_json: str,
    attestation: sqlite3.Row,
    *,
    action: str = INCARNATION_ATTEST_ACTION,
) -> dict[str, Any]:
    """Validate the immutable result envelope without consulting live locators."""
    try:
        result = json.loads(result_json)
    except (TypeError, ValueError, json.JSONDecodeError) as exc:
        raise ValueError("invalid incarnation attestation operation result") from exc
    expected_result_keys = (
        {"workspace", "binding", "attestation", "projection"}
        if action == INCARNATION_ATTEST_ACTION
        else {
            "workspace",
            "binding",
            "previous_binding",
            "source_proof",
            "attestation",
            "projection",
        }
        if action == INCARNATION_REBIND_ACTION
        else set()
    )
    if (
        not isinstance(result, dict)
        or _canonical_json(result) != result_json
        or set(result) != expected_result_keys
    ):
        raise ValueError("invalid incarnation attestation operation result")

    workspace = result.get("workspace")
    expected_workspace_keys = {
        "id",
        "name",
        "icon",
        "owner_subject_id",
        "version",
        "security_epoch",
        "members_can_create_teamspaces",
        "created_at",
        "updated_at",
    }
    integer_workspace_fields = (
        "version",
        "security_epoch",
        "created_at",
        "updated_at",
    )
    if (
        not isinstance(workspace, dict)
        or set(workspace) != expected_workspace_keys
        or workspace.get("id") != str(attestation["workspace_id"])
        or not isinstance(workspace.get("name"), str)
        or not isinstance(workspace.get("icon"), str)
        or not isinstance(workspace.get("owner_subject_id"), str)
        or not isinstance(workspace.get("members_can_create_teamspaces"), bool)
        or any(
            isinstance(workspace.get(field), bool)
            or not isinstance(workspace.get(field), int)
            or int(workspace[field]) < (1 if field in {"version", "security_epoch"} else 0)
            for field in integer_workspace_fields
        )
    ):
        raise ValueError("invalid incarnation attestation operation result")

    binding = result.get("binding")
    expected_binding = {
        "workspace_id": str(attestation["workspace_id"]),
        "source_owner_subject_id": str(attestation["source_owner_subject_id"]),
        "source_page_id": str(attestation["source_page_id"]),
        "state": binding.get("state") if isinstance(binding, dict) else None,
        "version": int(attestation["binding_version"]),
    }
    if (
        not isinstance(binding, dict)
        or binding != expected_binding
        or binding.get("state") not in (
            {"pending", "active"}
            if action == INCARNATION_ATTEST_ACTION
            else {"active"}
        )
        or result.get("attestation") != _incarnation_attestation_payload(attestation)
    ):
        raise ValueError("invalid incarnation attestation operation result")

    if action == INCARNATION_REBIND_ACTION:
        owner = str(attestation["source_owner_subject_id"])
        page_id = str(attestation["source_page_id"])
        binding_version = int(attestation["binding_version"])
        source_proof = result.get("source_proof")
        if (
            not isinstance(source_proof, dict)
            or set(source_proof)
            != {
                "actor_subject_id",
                "owner_subject_id",
                "page_id",
                "revision",
                "updated_at",
                "content_sha256",
            }
            or source_proof.get("actor_subject_id") != owner
            or source_proof.get("owner_subject_id") != owner
            or source_proof.get("page_id") != page_id
            or isinstance(source_proof.get("revision"), bool)
            or not isinstance(source_proof.get("revision"), int)
            or source_proof["revision"] < 1
            or isinstance(source_proof.get("updated_at"), bool)
            or not isinstance(source_proof.get("updated_at"), int)
            or source_proof["updated_at"] < 0
            or not re.fullmatch(
                r"sha256:[0-9a-f]{64}",
                str(source_proof.get("content_sha256") or ""),
            )
        ):
            raise ValueError("invalid incarnation attestation operation result")
        previous = result.get("previous_binding")
        if (
            not isinstance(previous, dict)
            or set(previous)
            != {
                "state",
                "version",
                "quarantine_reason",
                "quarantine_source_generation",
            }
            or previous.get("state") != "quarantined"
            or previous.get("version") != binding_version - 1
            or previous.get("quarantine_reason")
            not in PAGE_SOURCE_QUARANTINE_REASONS
            or isinstance(previous.get("quarantine_source_generation"), bool)
            or not isinstance(previous.get("quarantine_source_generation"), int)
            or not 1
            <= previous["quarantine_source_generation"]
            <= MAX_HEALING_SEQUENCE_VALUE
        ):
            raise ValueError("invalid incarnation attestation operation result")

    projection = result.get("projection")
    if binding["state"] == "pending":
        if projection is not None:
            raise ValueError("invalid incarnation attestation operation result")
        return result
    if (
        not isinstance(projection, dict)
        or set(projection)
        != {
            "binding_version",
            "projection_sha256",
            "file_source_count",
            "public_source_count",
            "changed",
        }
        or projection.get("binding_version") != int(attestation["binding_version"])
        or not re.fullmatch(
            r"sha256:[0-9a-f]{64}",
            str(projection.get("projection_sha256") or ""),
        )
        or isinstance(projection.get("file_source_count"), bool)
        or not isinstance(projection.get("file_source_count"), int)
        or not 0 <= projection["file_source_count"] <= MAX_FILE_SOURCES_PER_PAGE
        or isinstance(projection.get("public_source_count"), bool)
        or not isinstance(projection.get("public_source_count"), int)
        or not 0 <= projection["public_source_count"] <= MAX_PUBLIC_SOURCES_PER_PAGE
        or not isinstance(projection.get("changed"), bool)
    ):
        raise ValueError("invalid incarnation attestation operation result")
    return result


def _incarnation_operation_event_payload(
    result: dict[str, Any], *, action: str
) -> dict[str, Any]:
    """Return the exact secret-free event commitment for a reviewed generation."""
    if action == INCARNATION_ATTEST_ACTION:
        return {
            "attestation": result["attestation"],
            "projection": result["projection"],
        }
    if action == INCARNATION_REBIND_ACTION:
        return {
            "previous_binding": result["previous_binding"],
            "source_proof": result["source_proof"],
            "attestation": result["attestation"],
            "projection": result["projection"],
        }
    raise ValueError("invalid incarnation operation action")


def _validate_incarnation_operation_commitment_on_connection(
    con: sqlite3.Connection,
    attestation: sqlite3.Row,
    *,
    expected_action: str | None = None,
    require_current_projection: bool = False,
) -> dict[str, Any]:
    """Validate one complete immutable review/rebind commitment.

    This is the shared authority for replay, readiness, proof-actor
    derivation, and deep health.  A weaker JSON-path subset must never be used
    to make a generation resolver-ready or to return an exact replay.
    """
    actor = str(attestation["reviewed_by_subject_id"])
    operation_id = str(attestation["review_operation_id"])
    workspace_id = str(attestation["workspace_id"])
    owner = str(attestation["source_owner_subject_id"])
    page_id = str(attestation["source_page_id"])
    binding_version = int(attestation["binding_version"])
    operation = con.execute(
        """
        SELECT action,workspace_id,required_capability,
               authorization_strength,authorization_context_json,result_json
        FROM workspace_operations
        WHERE actor_subject_id=? AND operation_id=?
        """,
        (actor, operation_id),
    ).fetchone()
    if operation is None:
        raise WorkspaceSubstrateUnavailable(
            "page source incarnation operation ledger is invalid"
        )
    action = str(operation["action"])
    if (
        action not in {INCARNATION_ATTEST_ACTION, INCARNATION_REBIND_ACTION}
        or (expected_action is not None and action != expected_action)
        or str(operation["workspace_id"]) != workspace_id
    ):
        raise WorkspaceSubstrateUnavailable(
            "page source incarnation operation ledger is invalid"
        )
    try:
        authorization = WorkspaceStore._ledger_authorization(operation)
        expected_authorization = _AuthorizationRequirement(
            "workspace.page_source.bind_admin",
            {
                "workspace_id": workspace_id,
                "source_owner_subject_id": owner,
                "teamspace_id": "",
            },
        )
        if authorization != expected_authorization:
            raise ValueError("invalid incarnation operation authorization")
        result = _validate_incarnation_attestation_operation_result(
            str(operation["result_json"]),
            attestation,
            action=action,
        )
        expected_event = _incarnation_operation_event_payload(
            result, action=action
        )
        expected_payload_json = _canonical_json(expected_event)
        expected_target_id = f"{owner}:{page_id}:{binding_version}"
        audit_rows = con.execute(
            """
            SELECT action,target_type,target_id,payload_json
            FROM workspace_audit_events
            WHERE actor_subject_id=? AND operation_id=?
            """,
            (actor, operation_id),
        ).fetchall()
        outbox_rows = con.execute(
            """
            SELECT event_type,aggregate_type,aggregate_id,payload_json
            FROM workspace_outbox
            WHERE actor_subject_id=? AND operation_id=?
            """,
            (actor, operation_id),
        ).fetchall()
        if (
            len(audit_rows) != 1
            or len(outbox_rows) != 1
            or str(audit_rows[0]["action"]) != action
            or str(audit_rows[0]["target_type"])
            != "legacy_page_source_incarnation"
            or str(audit_rows[0]["target_id"]) != expected_target_id
            or str(audit_rows[0]["payload_json"]) != expected_payload_json
            or str(outbox_rows[0]["event_type"]) != action
            or str(outbox_rows[0]["aggregate_type"])
            != "legacy_page_source_incarnation"
            or str(outbox_rows[0]["aggregate_id"]) != expected_target_id
            or str(outbox_rows[0]["payload_json"]) != expected_payload_json
        ):
            raise ValueError("invalid incarnation operation event commitment")

        if require_current_projection:
            binding = con.execute(
                """
                SELECT state,row_version,source_revision,source_updated_at,
                       source_sha256
                FROM workspace_page_sources
                WHERE workspace_id=? AND source_owner_subject_id=?
                  AND source_page_id=?
                """,
                (workspace_id, owner, page_id),
            ).fetchone()
            projection = con.execute(
                """
                SELECT projection_sha256,file_source_count,public_source_count
                FROM workspace_page_source_projections
                WHERE workspace_id=? AND source_owner_subject_id=?
                  AND source_page_id=? AND binding_version=?
                """,
                (workspace_id, owner, page_id, binding_version),
            ).fetchone()
            file_sources = tuple(
                str(row["source_file_id"])
                for row in con.execute(
                    """
                    SELECT source_file_id FROM workspace_file_sources
                    WHERE workspace_id=? AND source_owner_subject_id=?
                      AND source_page_id=? AND binding_version=?
                    ORDER BY source_file_id
                    """,
                    (workspace_id, owner, page_id, binding_version),
                ).fetchall()
            )
            public_sources = tuple(
                (str(row["token_sha256"]), bool(row["allow_duplicate"]))
                for row in con.execute(
                    """
                    SELECT token_sha256,allow_duplicate
                    FROM workspace_public_sources
                    WHERE workspace_id=? AND source_owner_subject_id=?
                      AND source_page_id=? AND binding_version=?
                    ORDER BY token_sha256
                    """,
                    (workspace_id, owner, page_id, binding_version),
                ).fetchall()
            )
            expected_projection_sha256 = _page_projection_sha256(
                workspace_id=workspace_id,
                source_owner_subject_id=owner,
                source_page_id=page_id,
                binding_version=binding_version,
                file_sources=file_sources,
                public_sources=public_sources,
            )
            commitment = result["projection"]
            if (
                binding is None
                or str(binding["state"]) != "active"
                or int(binding["row_version"]) != binding_version
                or projection is None
                or commitment is None
                or commitment["projection_sha256"]
                != str(projection["projection_sha256"])
                or commitment["file_source_count"]
                != int(projection["file_source_count"])
                or commitment["public_source_count"]
                != int(projection["public_source_count"])
                or str(projection["projection_sha256"])
                != expected_projection_sha256
                or int(projection["file_source_count"]) != len(file_sources)
                or int(projection["public_source_count"]) != len(public_sources)
            ):
                raise ValueError("invalid current projection commitment")
            if action == INCARNATION_REBIND_ACTION:
                proof = result["source_proof"]
                if (
                    proof["revision"] != int(binding["source_revision"])
                    or proof["updated_at"] != int(binding["source_updated_at"])
                    or proof["content_sha256"] != str(binding["source_sha256"])
                ):
                    raise ValueError("invalid current rebound proof commitment")
    except (
        KeyError,
        TypeError,
        ValueError,
        json.JSONDecodeError,
        WorkspaceSubstrateUnavailable,
    ) as exc:
        if isinstance(exc, WorkspaceSubstrateUnavailable):
            raise
        raise WorkspaceSubstrateUnavailable(
            "page source incarnation operation ledger is invalid"
        ) from exc
    return result


def _validate_exact_incarnation_replay_on_connection(
    con: sqlite3.Connection,
    result: dict[str, Any],
    *,
    action: str,
    workspace_id: str,
    source_owner_subject_id: str,
    source_page_id: str,
    binding_version: int,
    reviewed_by_subject_id: str,
    review_operation_id: str,
) -> dict[str, Any]:
    """Validate an exact incarnation replay against its immutable evidence."""
    attestation = con.execute(
        """
        SELECT * FROM workspace_page_source_incarnation_attestations
        WHERE workspace_id=? AND source_owner_subject_id=?
          AND source_page_id=? AND binding_version=?
          AND reviewed_by_subject_id=? AND review_operation_id=?
        """,
        (
            workspace_id,
            source_owner_subject_id,
            source_page_id,
            binding_version,
            reviewed_by_subject_id,
            review_operation_id,
        ),
    ).fetchone()
    if attestation is None:
        raise WorkspaceSubstrateUnavailable(
            "workspace operation result ledger is invalid"
        )
    validated = _validate_incarnation_operation_commitment_on_connection(
        con,
        attestation,
        expected_action=action,
        require_current_projection=False,
    )
    if validated != result:
        raise WorkspaceSubstrateUnavailable(
            "workspace operation result ledger is invalid"
        )
    return validated


def page_source_proof_actor_on_connection(
    con: sqlite3.Connection, binding: sqlite3.Row
) -> str:
    """Derive the proof actor for one current page-source generation.

    ``bound_by_subject_id`` is immutable provenance, not necessarily the actor
    of the proof stored on a later explicit rebound generation.  A rebound is
    accepted only when its attestation, operation authorization/result, source
    proof, and locator projection form one exact immutable commitment.
    """
    bound_by = _subject(
        str(binding["bound_by_subject_id"]), field="bound_by_subject_id"
    )
    workspace_id = str(binding["workspace_id"])
    owner = str(binding["source_owner_subject_id"])
    page_id = str(binding["source_page_id"])
    version = int(binding["row_version"])
    attestation = con.execute(
        """
        SELECT * FROM workspace_page_source_incarnation_attestations
        WHERE workspace_id=? AND source_owner_subject_id=?
          AND source_page_id=? AND binding_version=?
        """,
        (workspace_id, owner, page_id, version),
    ).fetchone()
    if attestation is None:
        return bound_by
    operation = con.execute(
        """
        SELECT action FROM workspace_operations
        WHERE actor_subject_id=? AND operation_id=?
        """,
        (
            str(attestation["reviewed_by_subject_id"]),
            str(attestation["review_operation_id"]),
        ),
    ).fetchone()
    if operation is None:
        raise WorkspaceSubstrateUnavailable(
            "page source incarnation operation ledger is invalid"
        )
    action = str(operation["action"])
    if action == PAGE_LIFECYCLE_FINALIZED_ACTION:
        full_operation = con.execute(
            """
            SELECT * FROM workspace_operations
            WHERE actor_subject_id=? AND operation_id=?
            """,
            (
                str(attestation["reviewed_by_subject_id"]),
                str(attestation["review_operation_id"]),
            ),
        ).fetchone()
        if full_operation is None:
            raise WorkspaceSubstrateUnavailable(
                "page source incarnation operation ledger is invalid"
            )
        try:
            result = _validate_page_lifecycle_finalized_commitment_on_connection(
                con,
                full_operation,
                json.loads(str(full_operation["result_json"])),
                actor_subject_id=str(full_operation["actor_subject_id"]),
                operation_id=str(full_operation["operation_id"]),
                workspace_id=workspace_id,
            )
            if result.get("contract") == PAGE_LIFECYCLE_STRUCTURAL_RESULT_CONTRACT:
                effect = con.execute(
                    "SELECT * FROM workspace_page_lifecycle_structural_effects "
                    "WHERE command_id=? AND source_owner_subject_id=? "
                    "AND source_page_id=?",
                    (result["command_id"], owner, page_id),
                ).fetchone()
                projection = con.execute(
                    "SELECT projection_sha256 FROM workspace_page_source_projections "
                    "WHERE workspace_id=? AND source_owner_subject_id=? "
                    "AND source_page_id=? AND binding_version=?",
                    (workspace_id, owner, page_id, version),
                ).fetchone()
                if (
                    effect is None
                    or projection is None
                    or int(effect["source_mutated"]) != 1
                    or int(effect["after_binding_version"]) != version
                    or int(effect["after_source_revision"])
                    != int(binding["source_revision"])
                    or int(effect["after_source_updated_at"])
                    != int(binding["source_updated_at"])
                    or str(effect["after_page_sha256"])
                    != str(binding["source_sha256"])
                    or str(effect["after_incarnation_id"])
                    != str(attestation["source_incarnation_id"])
                    or int(effect["after_incarnation_generation"])
                    != int(attestation["source_incarnation_generation"])
                    or int(effect["after_change_generation"])
                    != int(attestation["source_change_generation"])
                    or str(effect["after_source_receipt_sha256"])
                    != str(attestation["source_receipt_sha256"])
                    or str(effect["after_locator_sha256"])
                    != str(projection["projection_sha256"])
                ):
                    raise ValueError("invalid structural lifecycle proof commitment")
                return owner
            if (
                not result.get("changed")
                or result["binding_version"] != version
                or result["source_revision"] != int(binding["source_revision"])
                or result["source_updated_at"] != int(binding["source_updated_at"])
                or result["source_sha256"] != str(binding["source_sha256"])
            ):
                raise ValueError("invalid lifecycle proof commitment")
            return owner
        except (KeyError, TypeError, ValueError, json.JSONDecodeError) as exc:
            raise WorkspaceSubstrateUnavailable(
                "page source incarnation operation ledger is invalid"
            ) from exc
    if action not in {INCARNATION_ATTEST_ACTION, INCARNATION_REBIND_ACTION}:
        raise WorkspaceSubstrateUnavailable(
            "page source incarnation operation ledger is invalid"
        )
    try:
        result = _validate_incarnation_operation_commitment_on_connection(
            con,
            attestation,
            expected_action=action,
            require_current_projection=True,
        )
        if action == INCARNATION_ATTEST_ACTION:
            return bound_by
        proof = result["source_proof"]
        if (
            proof["actor_subject_id"] != owner
            or proof["owner_subject_id"] != owner
            or proof["page_id"] != page_id
            or proof["revision"] != int(binding["source_revision"])
            or proof["updated_at"] != int(binding["source_updated_at"])
            or proof["content_sha256"] != str(binding["source_sha256"])
        ):
            raise ValueError("invalid rebound proof commitment")
        projection = con.execute(
            """
            SELECT projection_sha256,file_source_count,public_source_count
            FROM workspace_page_source_projections
            WHERE workspace_id=? AND source_owner_subject_id=?
              AND source_page_id=? AND binding_version=?
            """,
            (workspace_id, owner, page_id, version),
        ).fetchone()
        commitment = result["projection"]
        if (
            projection is None
            or commitment["projection_sha256"]
            != str(projection["projection_sha256"])
            or commitment["file_source_count"]
            != int(projection["file_source_count"])
            or commitment["public_source_count"]
            != int(projection["public_source_count"])
        ):
            raise ValueError("invalid rebound projection commitment")
    except (KeyError, TypeError, ValueError, json.JSONDecodeError) as exc:
        raise WorkspaceSubstrateUnavailable(
            "page source incarnation operation ledger is invalid"
        ) from exc
    return owner


def _page_projection_sha256(
    *,
    workspace_id: str,
    source_owner_subject_id: str,
    source_page_id: str,
    binding_version: int,
    file_sources: tuple[str, ...],
    public_sources: tuple[tuple[str, bool], ...],
) -> str:
    payload = {
        "workspace_id": workspace_id,
        "source_owner_subject_id": source_owner_subject_id,
        "source_page_id": source_page_id,
        "binding_version": binding_version,
        "file_sources": list(file_sources),
        "public_sources": [
            {
                "token_sha256": token_sha256,
                "allow_duplicate": allow_duplicate,
            }
            for token_sha256, allow_duplicate in public_sources
        ],
    }
    return "sha256:" + hashlib.sha256(
        _canonical_json(payload).encode("utf-8")
    ).hexdigest()


def _normalize_healing_source_fence(
    value: WorkspaceHealingSourceFence,
) -> WorkspaceHealingSourceFence:
    if not isinstance(value, WorkspaceHealingSourceFence):
        raise ValueError("WorkspaceHealingSourceFence required")
    def sqlite_identity(item: Any, *, field: str) -> int:
        if isinstance(item, bool) or not isinstance(item, int):
            raise ValueError(f"{field} must be an integer")
        if -9_223_372_036_854_775_808 <= item <= 9_223_372_036_854_775_807:
            return item
        if 9_223_372_036_854_775_807 < item <= 18_446_744_073_709_551_615:
            return item - 18_446_744_073_709_551_616
        raise ValueError(f"{field} must be a 64-bit identity")

    fields = {
        "source_epoch": value.source_epoch,
        "full_sweep_generation": value.full_sweep_generation,
        "source_device": sqlite_identity(value.source_device, field="source_device"),
        "source_inode": sqlite_identity(value.source_inode, field="source_inode"),
        "source_link_count": value.source_link_count,
    }
    for field, item in fields.items():
        if field in {"source_device", "source_inode"}:
            continue
        minimum = 1
        maximum = {
            "source_epoch": MAX_HEALING_SEQUENCE_VALUE,
            "full_sweep_generation": MAX_HEALING_SEQUENCE_VALUE,
            "source_link_count": 65_535,
        }[field]
        _bounded_integer(item, field=field, minimum=minimum, maximum=maximum)
    return WorkspaceHealingSourceFence(**fields)


def _page_healing_source_receipt(
    value: LegacyPageHealingCandidate | LegacyPageQuarantineCandidate,
) -> dict[str, Any]:
    """Return the identifier-free source receipt committed by one page effect."""
    return {
        "source_epoch": value.source_epoch,
        "full_sweep_generation": value.full_sweep_generation,
        "change_generation": value.change_generation,
        "change_mask": value.change_mask,
        "source_exists": value.source_exists,
        "source_active": value.source_active,
    }


def _validate_page_healing_source_receipt(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict) or set(value) != {
        "source_epoch",
        "full_sweep_generation",
        "change_generation",
        "change_mask",
        "source_exists",
        "source_active",
    }:
        raise WorkspaceSubstrateUnavailable(
            "workspace healing effect ledger is invalid"
        )
    normalized = {
        "source_epoch": _bounded_integer(
            value.get("source_epoch"),
            field="source_epoch",
            minimum=1,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        "full_sweep_generation": _bounded_integer(
            value.get("full_sweep_generation"),
            field="full_sweep_generation",
            minimum=1,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        "change_generation": _bounded_integer(
            value.get("change_generation"),
            field="change_generation",
            minimum=1,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        "change_mask": _bounded_integer(
            value.get("change_mask"),
            field="change_mask",
            minimum=1,
            maximum=31,
        ),
        "source_exists": value.get("source_exists"),
        "source_active": value.get("source_active"),
    }
    if not isinstance(normalized["source_exists"], bool) or not isinstance(
        normalized["source_active"], bool
    ):
        raise WorkspaceSubstrateUnavailable(
            "workspace healing effect ledger is invalid"
        )
    if normalized["source_active"] and not normalized["source_exists"]:
        raise WorkspaceSubstrateUnavailable(
            "workspace healing effect ledger is invalid"
        )
    return normalized


def _validate_page_source_healing_operation_result(
    value: Any,
    *,
    workspace_id: str,
    run_id: str,
    worker: str,
    lease_token_sha256: str,
    fencing_generation: int,
    expected_version: int,
    expected_binding_version: int,
    owner_subject_id: str,
    page_id: str,
) -> dict[str, Any]:
    """Authenticate the durable result used by effect replay and future ack."""
    try:
        if not isinstance(value, dict) or set(value) != {
            "workspace",
            "healing",
            "_run_id",
            "_lease_worker",
            "_lease_token_sha256",
            "_fencing_generation",
            "_expected_version",
            "_expected_binding_version",
            "_source_owner_subject_id",
            "_source_page_id",
            "_source_receipt",
        }:
            raise ValueError("result must be an object")
        workspace = value.get("workspace")
        healing = value.get("healing")
        if (
            not isinstance(workspace, dict)
            or set(workspace) != {
                "id",
                "name",
                "icon",
                "owner_subject_id",
                "version",
                "security_epoch",
                "members_can_create_teamspaces",
                "created_at",
                "updated_at",
            }
            or str(workspace.get("id") or "") != workspace_id
            or not isinstance(workspace.get("members_can_create_teamspaces"), bool)
            or not isinstance(healing, dict)
            or set(healing) != {
                "run_id",
                "binding_version",
                "disposition",
                "changed",
                "file_source_count",
                "public_source_count",
                "source_receipt",
            }
            or str(healing.get("run_id") or "") != run_id
            or str(healing.get("disposition") or "")
            not in {
                "match",
                "safe_miss",
                "stale",
                "superseded",
                "ambiguous",
                "permission_mismatch",
                "unsafe_path",
                "oversize",
                "source_missing",
            }
            or not isinstance(healing.get("changed"), bool)
        ):
            raise ValueError("healing result identity is invalid")
        for field in ("version", "security_epoch"):
            _bounded_integer(
                workspace.get(field),
                field=f"workspace.{field}",
                minimum=1,
                maximum=MAX_HEALING_SEQUENCE_VALUE,
            )
        for field in ("created_at", "updated_at"):
            _bounded_integer(
                workspace.get(field),
                field=f"workspace.{field}",
                minimum=0,
                maximum=MAX_HEALING_TIMESTAMP,
            )
        if workspace["updated_at"] < workspace["created_at"]:
            raise ValueError("workspace timestamps are invalid")
        for field, maximum in (
            ("binding_version", MAX_HEALING_SEQUENCE_VALUE),
            ("file_source_count", MAX_FILE_SOURCES_PER_PAGE),
            ("public_source_count", MAX_PUBLIC_SOURCES_PER_PAGE),
        ):
            _bounded_integer(
                healing.get(field),
                field=field,
                minimum=0 if field != "binding_version" else 1,
                maximum=maximum,
            )
        receipt = _validate_page_healing_source_receipt(
            healing.get("source_receipt")
        )
        if (
            value.get("_source_receipt") != receipt
            or str(value.get("_run_id") or "") != run_id
            or str(value.get("_lease_worker") or "") != worker
            or str(value.get("_lease_token_sha256") or "") != lease_token_sha256
            or value.get("_fencing_generation") != fencing_generation
            or value.get("_expected_version") != expected_version
            or value.get("_expected_binding_version") != expected_binding_version
            or str(value.get("_source_owner_subject_id") or "")
            != owner_subject_id
            or str(value.get("_source_page_id") or "") != page_id
        ):
            raise ValueError("healing result fence is invalid")
    except WorkspaceSubstrateUnavailable:
        raise
    except (TypeError, ValueError) as exc:
        raise WorkspaceSubstrateUnavailable(
            "workspace healing effect ledger is invalid"
        ) from exc
    return {
        key: item for key, item in value.items() if not str(key).startswith("_")
    }


def _normalize_page_healing_candidate(
    value: LegacyPageHealingCandidate,
) -> LegacyPageHealingCandidate:
    if not isinstance(value, LegacyPageHealingCandidate):
        raise ValueError("LegacyPageHealingCandidate required")
    workspace_id = _identifier(
        value.workspace_id, prefix="ws", field="candidate.workspace_id"
    )
    owner = _subject(value.owner_subject_id, field="candidate.owner_subject_id")
    bound_by = _subject(
        value.bound_by_subject_id, field="candidate.bound_by_subject_id"
    )
    proof_actor = _subject(
        value.proof_actor_subject_id, field="candidate.proof_actor_subject_id"
    )
    page_id = str(value.page_id or "")
    if not page_id or page_id != page_id.strip() or len(page_id) > 160:
        raise ValueError("valid candidate.page_id required")
    workspace_version = _expected_version(value.workspace_version)
    binding_version = _expected_version(value.binding_version)
    if value.binding_state not in {"active", "quarantined"}:
        raise ValueError("valid candidate.binding_state required")
    fence = _normalize_healing_source_fence(value.source_fence())
    change_generation = _bounded_integer(
        value.change_generation,
        field="candidate.change_generation",
        minimum=1,
        maximum=MAX_HEALING_SEQUENCE_VALUE,
    )
    change_mask = _bounded_integer(
        value.change_mask,
        field="candidate.change_mask",
        minimum=1,
        maximum=31,
    )
    if not isinstance(value.source_exists, bool) or not isinstance(
        value.source_active, bool
    ):
        raise ValueError("candidate source state must be boolean")
    if value.source_active and not value.source_exists:
        raise ValueError("active legacy source must exist")
    if not isinstance(value.file_sources, tuple) or not isinstance(
        value.public_sources, tuple
    ):
        raise ValueError("candidate locators must be immutable tuples")
    file_sources = tuple(value.file_sources)
    public_sources = tuple(value.public_sources)
    if value.source_active:
        proof = value.source_proof
        if not isinstance(proof, LegacyPageSourceProof):
            raise ValueError("active candidate requires source proof")
        if (
            proof.owner_subject_id != owner
            or proof.page_id != page_id
            or proof.actor_subject_id != proof_actor
        ):
            raise ValueError("candidate source proof identity mismatch")
        if (
            isinstance(proof.revision, bool)
            or not isinstance(proof.revision, int)
            or proof.revision < 1
            or isinstance(proof.updated_at, bool)
            or not isinstance(proof.updated_at, int)
            or proof.updated_at < 0
            or not re.fullmatch(r"sha256:[0-9a-f]{64}", proof.content_sha256)
        ):
            raise ValueError("candidate source proof is invalid")
    else:
        proof = None
        if value.source_proof is not None or file_sources or public_sources:
            raise ValueError("inactive candidate must not carry source locators")
    if len(file_sources) > MAX_FILE_SOURCES_PER_PAGE:
        raise ValueError("too many candidate file sources")
    normalized_files: list[LegacyFileSourceLocator] = []
    for item in file_sources:
        if not isinstance(item, LegacyFileSourceLocator):
            raise ValueError("LegacyFileSourceLocator required")
        normalized_files.append(LegacyFileSourceLocator(_source_file_id(item.source_file_id)))
    if [item.source_file_id for item in normalized_files] != sorted(
        item.source_file_id for item in normalized_files
    ) or len({item.source_file_id for item in normalized_files}) != len(
        normalized_files
    ):
        raise ValueError("candidate file sources must be sorted and unique")
    if len(public_sources) > MAX_PUBLIC_SOURCES_PER_PAGE:
        raise ValueError("too many candidate public sources")
    normalized_public: list[LegacyPublicSourceLocator] = []
    for item in public_sources:
        if not isinstance(item, LegacyPublicSourceLocator) or not isinstance(
            item.allow_duplicate, bool
        ):
            raise ValueError("LegacyPublicSourceLocator required")
        normalized_public.append(
            LegacyPublicSourceLocator(
                _sha256_digest(item.token_sha256, field="token_sha256"),
                item.allow_duplicate,
            )
        )
    if [item.token_sha256 for item in normalized_public] != sorted(
        item.token_sha256 for item in normalized_public
    ) or len({item.token_sha256 for item in normalized_public}) != len(
        normalized_public
    ):
        raise ValueError("candidate public sources must be sorted and unique")
    return LegacyPageHealingCandidate(
        workspace_id=workspace_id,
        workspace_version=workspace_version,
        owner_subject_id=owner,
        page_id=page_id,
        binding_version=binding_version,
        binding_state=value.binding_state,
        bound_by_subject_id=bound_by,
        proof_actor_subject_id=proof_actor,
        source_epoch=fence.source_epoch,
        full_sweep_generation=fence.full_sweep_generation,
        source_device=fence.source_device,
        source_inode=fence.source_inode,
        source_link_count=fence.source_link_count,
        change_generation=change_generation,
        change_mask=change_mask,
        source_exists=value.source_exists,
        source_active=value.source_active,
        source_proof=proof,
        file_sources=tuple(normalized_files),
        public_sources=tuple(normalized_public),
    )


def _normalize_page_quarantine_candidate(
    value: LegacyPageQuarantineCandidate,
) -> LegacyPageQuarantineCandidate:
    if not isinstance(value, LegacyPageQuarantineCandidate):
        raise ValueError("LegacyPageQuarantineCandidate required")
    workspace_id = _identifier(
        value.workspace_id, prefix="ws", field="candidate.workspace_id"
    )
    owner = _subject(value.owner_subject_id, field="candidate.owner_subject_id")
    bound_by = _subject(
        value.bound_by_subject_id, field="candidate.bound_by_subject_id"
    )
    proof_actor = _subject(
        value.proof_actor_subject_id, field="candidate.proof_actor_subject_id"
    )
    page_id = str(value.page_id or "")
    if not page_id or page_id != page_id.strip() or len(page_id) > 160:
        raise ValueError("valid candidate.page_id required")
    workspace_version = _expected_version(value.workspace_version)
    binding_version = _expected_version(value.binding_version)
    if value.binding_state not in {"active", "quarantined"}:
        raise ValueError("valid candidate.binding_state required")
    fence = _normalize_healing_source_fence(value.source_fence())
    change_generation = _bounded_integer(
        value.change_generation,
        field="candidate.change_generation",
        minimum=1,
        maximum=MAX_HEALING_SEQUENCE_VALUE,
    )
    change_mask = _bounded_integer(
        value.change_mask,
        field="candidate.change_mask",
        minimum=1,
        maximum=31,
    )
    if not isinstance(value.source_exists, bool) or not isinstance(
        value.source_active, bool
    ):
        raise ValueError("candidate source state must be boolean")
    if not value.source_exists or not value.source_active:
        raise ValueError("permanent source refusal requires an active source page")
    reason = str(value.quarantine_reason or "")
    if reason not in SOURCE_HEALING_QUARANTINE_REASONS:
        raise ValueError("valid source healing quarantine reason required")
    return LegacyPageQuarantineCandidate(
        workspace_id=workspace_id,
        workspace_version=workspace_version,
        owner_subject_id=owner,
        page_id=page_id,
        binding_version=binding_version,
        binding_state=value.binding_state,
        bound_by_subject_id=bound_by,
        proof_actor_subject_id=proof_actor,
        source_epoch=fence.source_epoch,
        full_sweep_generation=fence.full_sweep_generation,
        source_device=fence.source_device,
        source_inode=fence.source_inode,
        source_link_count=fence.source_link_count,
        change_generation=change_generation,
        change_mask=change_mask,
        source_exists=value.source_exists,
        source_active=value.source_active,
        quarantine_reason=reason,
    )


def _fingerprint_value(value: Any) -> list[Any]:
    if value is None:
        return ["null", None]
    if isinstance(value, bytes):
        return ["blob", len(value), hashlib.sha256(value).hexdigest()]
    if isinstance(value, int):
        return ["integer", str(value)]
    if isinstance(value, float):
        return ["real", value.hex()]
    return ["text", str(value)]


def logical_database_fingerprint_on_connection(con: sqlite3.Connection) -> str:
    """Return a deterministic logical fingerprint from the current snapshot.

    This bounded-by-explicit-use helper exists for offline migration fencing;
    request paths continue to use the much cheaper schema-readiness check.
    """
    digest = hashlib.sha256()
    objects = con.execute(
        """
        SELECT type,name,tbl_name,COALESCE(sql,'') AS sql
        FROM sqlite_master WHERE name NOT LIKE 'sqlite_%'
        ORDER BY type,name,tbl_name
        """
    ).fetchall()
    digest.update(_canonical_json([
        [str(row["type"]), str(row["name"]), str(row["tbl_name"]),
         " ".join(str(row["sql"] or "").split())]
        for row in objects
    ]).encode("utf-8"))
    for table in sorted(
        str(row["name"]) for row in objects if str(row["type"]) == "table"
    ):
        quoted = '"' + table.replace('"', '""') + '"'
        columns = [
            str(row["name"])
            for row in con.execute(f"PRAGMA table_info({quoted})").fetchall()
        ]
        rows = sorted(
            _canonical_json([_fingerprint_value(value) for value in tuple(row)])
            for row in con.execute(f"SELECT * FROM {quoted}").fetchall()
        )
        digest.update(_canonical_json([table, columns, rows]).encode("utf-8"))
    digest.update(_canonical_json([
        int(con.execute("PRAGMA application_id").fetchone()[0]),
        int(con.execute("PRAGMA user_version").fetchone()[0]),
    ]).encode("utf-8"))
    return "sha256:" + digest.hexdigest()


def _actual_schema_sha256(con: sqlite3.Connection) -> str:
    rows = con.execute(
        """
        SELECT type,name,tbl_name,COALESCE(sql,'') AS sql
        FROM sqlite_master
        WHERE name NOT LIKE 'sqlite_%'
        ORDER BY type,name,tbl_name
        """
    ).fetchall()
    payload = [
        {
            "type": str(row["type"]),
            "name": str(row["name"]),
            "table": str(row["tbl_name"]),
            "sql": " ".join(str(row["sql"] or "").split()),
        }
        for row in rows
    ]
    return "sha256:" + hashlib.sha256(_canonical_json(payload).encode("utf-8")).hexdigest()


def _schema_ready_on_connection(con: sqlite3.Connection) -> bool:
    """Bounded request-path readiness check.

    This intentionally inspects only the small schema catalog and the signed
    migration row.  Full database, FK, and semantic scans belong to the
    explicit deep-health API and are never repeated for every request.
    """
    objects = {
        (str(row["type"]), str(row["name"]))
        for row in con.execute(
            "SELECT type,name FROM sqlite_master WHERE name NOT LIKE 'sqlite_%'"
        ).fetchall()
    }
    if not all(("table", name) in objects for name in _REQUIRED_TABLES):
        return False
    if not all(("index", name) in objects for name in _REQUIRED_INDEXES):
        return False
    if not all(("trigger", name) in objects for name in _REQUIRED_TRIGGERS):
        return False
    migration_columns = {
        str(row["name"])
        for row in con.execute("PRAGMA table_info(workspace_schema_migrations)").fetchall()
    }
    if "actual_schema_sha256" not in migration_columns:
        return False
    row = con.execute(
        """
        SELECT name,checksum,actual_schema_sha256
        FROM workspace_schema_migrations WHERE version=?
        """,
        (SCHEMA_VERSION,),
    ).fetchone()
    if not row or (
        str(row["name"]), str(row["checksum"])
    ) != (SCHEMA_MIGRATION_NAME, _SCHEMA_CHECKSUM):
        return False
    if str(row["actual_schema_sha256"]) != _actual_schema_sha256(con):
        return False
    return True


def _request_hash(actor: str, action: str, request: dict[str, Any]) -> str:
    payload = _canonical_json({"actor": actor, "action": action, "request": request})
    return "sha256:" + hashlib.sha256(payload.encode("utf-8")).hexdigest()


def _dict(row: sqlite3.Row | None) -> dict[str, Any] | None:
    return dict(row) if row is not None else None


def _incarnation_attestation_counts_on_connection(
    con: sqlite3.Connection,
    *,
    workspace_id: str | None = None,
) -> dict[str, int | bool]:
    """Return identifier-free current-generation attestation readiness counts."""
    where = "WHERE ps.workspace_id=?" if workspace_id is not None else ""
    parameters: tuple[str, ...] = (workspace_id,) if workspace_id is not None else ()
    row = con.execute(
        f"""
        SELECT
          COUNT(*) AS binding_count,
          COALESCE(SUM(CASE WHEN ps.state='active' THEN 1 ELSE 0 END),0)
            AS active_binding_count,
          COALESCE(SUM(CASE WHEN ps.state='pending' THEN 1 ELSE 0 END),0)
            AS pending_binding_count,
          COALESCE(SUM(CASE WHEN ps.state='quarantined' THEN 1 ELSE 0 END),0)
            AS quarantined_binding_count,
          COALESCE(SUM(CASE WHEN ps.state='active' AND EXISTS (
            SELECT 1
            FROM workspace_page_source_incarnation_attestations a
            WHERE a.workspace_id=ps.workspace_id
              AND a.source_owner_subject_id=ps.source_owner_subject_id
              AND a.source_page_id=ps.source_page_id
              AND a.binding_version=ps.row_version
          ) THEN 1 ELSE 0 END),0) AS attested_active_binding_count,
          COALESCE(SUM(CASE WHEN ps.state='pending' AND EXISTS (
            SELECT 1
            FROM workspace_page_source_incarnation_attestations a
            WHERE a.workspace_id=ps.workspace_id
              AND a.source_owner_subject_id=ps.source_owner_subject_id
              AND a.source_page_id=ps.source_page_id
              AND a.binding_version=ps.row_version
          ) THEN 1 ELSE 0 END),0) AS attested_pending_binding_count
        FROM workspace_page_sources ps
        {where}
        """,
        parameters,
    ).fetchone()
    attestation_where = "WHERE workspace_id=?" if workspace_id is not None else ""
    attestation_count = int(
        con.execute(
            "SELECT COUNT(*) FROM workspace_page_source_incarnation_attestations "
            + attestation_where,
            parameters,
        ).fetchone()[0]
    )
    binding_count = int(row["binding_count"])
    active_count = int(row["active_binding_count"])
    pending_count = int(row["pending_binding_count"])
    quarantined_count = int(row["quarantined_binding_count"])
    attested_active = int(row["attested_active_binding_count"])
    attested_pending = int(row["attested_pending_binding_count"])
    current_rows = con.execute(
        """
        SELECT a.*
        FROM workspace_page_sources ps
        JOIN workspace_page_source_incarnation_attestations a
          ON a.workspace_id=ps.workspace_id
         AND a.source_owner_subject_id=ps.source_owner_subject_id
         AND a.source_page_id=ps.source_page_id
         AND a.binding_version=ps.row_version
        WHERE ps.state='active'
          AND (? IS NULL OR ps.workspace_id=?)
        ORDER BY ps.workspace_id,ps.source_owner_subject_id,ps.source_page_id
        """,
        (workspace_id, workspace_id),
    ).fetchall()
    validated_active = 0
    for attestation in current_rows:
        try:
            _validate_incarnation_operation_commitment_on_connection(
                con,
                attestation,
                require_current_projection=True,
            )
        except WorkspaceSubstrateUnavailable:
            continue
        validated_active += 1
    current_attestation_count = attested_active + attested_pending
    return {
        "binding_count": binding_count,
        "active_binding_count": active_count,
        "pending_binding_count": pending_count,
        "quarantined_binding_count": quarantined_count,
        "attestation_count": attestation_count,
        "current_attestation_count": current_attestation_count,
        "historical_attestation_count": attestation_count - current_attestation_count,
        "attested_active_binding_count": attested_active,
        "unattested_active_binding_count": active_count - attested_active,
        "attested_pending_binding_count": attested_pending,
        "unattested_pending_binding_count": pending_count - attested_pending,
        # A pending attestation can later be activated without changing its
        # binding version.  Do not call that generation resolver-ready until
        # its full immutable operation/event commitment and exact current
        # locator projection both validate through the shared authority.
        "ready_for_resolver_cutover": (
            pending_count == 0 and active_count == validated_active
        ),
    }


@dataclass(frozen=True)
class _AuthorizationRequirement:
    capability: str
    context: dict[str, Any]


@dataclass(frozen=True)
class _MutationEffect:
    result: dict[str, Any]
    workspace_id: str
    target_type: str
    target_id: str
    event_payload: dict[str, Any]
    authorization: _AuthorizationRequirement


def _normalize_page_lifecycle_request(
    value: WorkspacePageLifecycleCommandRequest,
) -> WorkspacePageLifecycleCommandRequest:
    if not isinstance(value, WorkspacePageLifecycleCommandRequest):
        raise ValueError("WorkspacePageLifecycleCommandRequest required")
    workspace_id = _identifier(
        value.workspace_id, prefix="ws", field="workspace_id"
    )
    action = str(value.action or "")
    if action not in {
        "rename", "create", "move", "reorder", "duplicate", "archive", "restore"
    }:
        raise ValueError("page lifecycle action is not enabled in this kernel slice")
    owner = _subject(
        value.source_owner_subject_id, field="source_owner_subject_id"
    )
    page_id = _source_page_identifier(value.source_page_id)
    parent_owner = (
        _subject(value.parent_source_owner_subject_id, field="parent_source_owner_subject_id")
        if value.parent_source_owner_subject_id
        else ""
    )
    parent_page = (
        _source_page_identifier(value.parent_source_page_id)
        if value.parent_source_page_id
        else ""
    )
    relative_owner = (
        _subject(value.relative_source_owner_subject_id, field="relative_source_owner_subject_id")
        if value.relative_source_owner_subject_id
        else ""
    )
    relative_page = (
        _source_page_identifier(value.relative_source_page_id)
        if value.relative_source_page_id
        else ""
    )
    relative_position = str(value.relative_position or "")
    if bool(parent_owner) != bool(parent_page):
        raise ValueError("page lifecycle parent identity must be complete")
    if bool(relative_owner) != bool(relative_page) or bool(relative_page) != bool(
        relative_position
    ):
        raise ValueError("page lifecycle relative identity must be complete")
    if relative_position not in {"", "before", "after"}:
        raise ValueError("valid page lifecycle relative_position required")
    if parent_owner and parent_owner != owner:
        raise ValueError("page lifecycle parent must use the source owner")
    if relative_owner and relative_owner != owner:
        raise ValueError("page lifecycle relative page must use the source owner")
    if page_id in {parent_page, relative_page}:
        raise ValueError("page lifecycle target cannot reference itself")
    if action in {"rename", "duplicate", "archive"} and any(
        (parent_owner, parent_page, relative_owner, relative_page, relative_position)
    ):
        raise ValueError(
            f"{action} lifecycle command does not accept structural targets"
        )
    if action == "create" and any(
        (relative_owner, relative_page, relative_position)
    ):
        raise ValueError("create lifecycle command does not accept a relative target")
    expected_binding_minimum = 0 if action == "create" else 1
    expected_incarnation_minimum = 0 if action == "create" else 1
    expected_binding = _bounded_integer(
        value.expected_binding_version,
        field="expected_binding_version",
        minimum=expected_binding_minimum,
        maximum=MAX_HEALING_SEQUENCE_VALUE,
    )
    expected_incarnation = _bounded_integer(
        value.expected_incarnation_generation,
        field="expected_incarnation_generation",
        minimum=expected_incarnation_minimum,
        maximum=MAX_HEALING_SEQUENCE_VALUE,
    )
    if action == "create" and (expected_binding != 0 or expected_incarnation != 0):
        raise ValueError("create lifecycle command requires an absent target")
    normalized = WorkspacePageLifecycleCommandRequest(
        workspace_id=workspace_id,
        action=action,
        source_owner_subject_id=owner,
        source_page_id=page_id,
        expected_tree_version=_bounded_integer(
            value.expected_tree_version,
            field="expected_tree_version",
            minimum=1,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        expected_binding_version=expected_binding,
        expected_incarnation_generation=expected_incarnation,
        base_version=_expected_version(value.base_version),
        parent_source_owner_subject_id=parent_owner,
        parent_source_page_id=parent_page,
        relative_source_owner_subject_id=relative_owner,
        relative_source_page_id=relative_page,
        relative_position=relative_position,
    )
    if normalized != value:
        raise ValueError("page lifecycle request must be canonical")
    return normalized


def _normalize_page_lifecycle_source_receipt(
    value: WorkspacePageLifecycleSourceReceipt,
) -> WorkspacePageLifecycleSourceReceipt:
    if not isinstance(value, WorkspacePageLifecycleSourceReceipt):
        raise ValueError("WorkspacePageLifecycleSourceReceipt required")
    normalized = WorkspacePageLifecycleSourceReceipt(
        source_receipt_sha256=_sha256_digest(
            value.source_receipt_sha256, field="source_receipt_sha256"
        ),
        affected_node_count=_bounded_integer(
            value.affected_node_count,
            field="affected_node_count",
            minimum=0,
            maximum=MAX_PAGE_TREE_SYNCHRONOUS_SUBTREE_NODES,
        ),
        file_work_count=_bounded_integer(
            value.file_work_count,
            field="file_work_count",
            minimum=0,
            maximum=MAX_FILE_SOURCES_PER_PAGE,
        ),
    )
    if normalized != value:
        raise ValueError("page lifecycle source receipt must be canonical")
    return normalized


def _normalize_page_lifecycle_structural_candidate(
    value: WorkspacePageLifecycleStructuralCandidate,
) -> WorkspacePageLifecycleStructuralCandidate:
    if not isinstance(value, WorkspacePageLifecycleStructuralCandidate):
        raise ValueError("WorkspacePageLifecycleStructuralCandidate required")
    action = str(value.action or "")
    if action not in {"create", "move", "reorder"}:
        raise ValueError("valid structural lifecycle action required")
    if value.source_changed is not True or type(value.structure_changed) is not bool:
        raise ValueError("structural lifecycle disposition is invalid")
    if action in {"create", "move"} and not value.structure_changed:
        raise ValueError("structural lifecycle action must change structure")
    fence = value.source_fence
    if not isinstance(fence, WorkspacePageTreeSourceFence):
        raise ValueError("WorkspacePageTreeSourceFence required")
    owner = _subject(
        fence.source_owner_subject_id, field="source_fence.source_owner_subject_id"
    )
    normalized_fence = WorkspacePageTreeSourceFence(
        source_owner_subject_id=owner,
        source_epoch=_bounded_integer(
            fence.source_epoch, field="source_epoch", minimum=1,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        full_sweep_generation=_bounded_integer(
            fence.full_sweep_generation, field="full_sweep_generation", minimum=1,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        source_device=sqlite_source_identity(fence.source_device),
        source_inode=sqlite_source_identity(fence.source_inode),
        source_link_count=_bounded_integer(
            fence.source_link_count, field="source_link_count", minimum=1,
            maximum=65535,
        ),
    )
    if normalized_fence != fence:
        raise ValueError("source fence must be canonical")
    old_parent = (
        _source_page_identifier(value.old_parent_source_page_id)
        if value.old_parent_source_page_id
        else ""
    )
    new_parent = (
        _source_page_identifier(value.new_parent_source_page_id)
        if value.new_parent_source_page_id
        else ""
    )
    if action == "create" and old_parent:
        raise ValueError("create structural candidate has an old parent")
    if action == "move" and old_parent == new_parent:
        raise ValueError("move structural candidate must change parent")
    if action == "reorder" and old_parent != new_parent:
        raise ValueError("reorder structural candidate must preserve parent")

    effects = value.effects
    if (
        not isinstance(effects, tuple)
        or not 1 <= len(effects) <= MAX_PAGE_LIFECYCLE_STRUCTURAL_EFFECTS
    ):
        raise ValueError("bounded immutable structural effects required")
    normalized_effects: list[WorkspacePageLifecycleStructuralEffectCandidate] = []
    pages: set[str] = set()
    target_effects: list[WorkspacePageLifecycleStructuralEffectCandidate] = []
    for index, raw in enumerate(effects, start=1):
        if not isinstance(raw, WorkspacePageLifecycleStructuralEffectCandidate):
            raise ValueError("WorkspacePageLifecycleStructuralEffectCandidate required")
        ordinal = _bounded_integer(
            raw.effect_ordinal, field="effect_ordinal", minimum=1,
            maximum=MAX_PAGE_LIFECYCLE_STRUCTURAL_EFFECTS,
        )
        if ordinal != index:
            raise ValueError("structural effects must be dense and canonical")
        roles = _bounded_integer(
            raw.effect_roles, field="effect_roles", minimum=1,
            maximum=PAGE_LIFECYCLE_EFFECT_ROLE_MASK,
        )
        if type(raw.source_mutated) is not bool:
            raise ValueError("structural source_mutated must be boolean")
        proof = _normalize_owner_canonical_source_proof(raw.source_proof)
        evidence = _normalize_incarnation_evidence(raw.source_incarnation)
        if (
            proof.owner_subject_id != owner
            or evidence.owner_subject_id != owner
            or proof.page_id != evidence.page_id
            or evidence.incarnation_retired
            or not evidence.source_exists
            or not evidence.source_active
            or evidence.source_device != normalized_fence.source_device
            or evidence.source_inode != normalized_fence.source_inode
            or evidence.source_link_count != normalized_fence.source_link_count
            or evidence.source_epoch > normalized_fence.source_epoch
            or evidence.full_sweep_generation
            > normalized_fence.full_sweep_generation
        ):
            raise ValueError("structural page evidence is outside its source fence")
        if raw.source_mutated and (
            evidence.source_epoch != normalized_fence.source_epoch
            or evidence.full_sweep_generation
            != normalized_fence.full_sweep_generation
        ):
            raise ValueError("mutated structural page must use the current source fence")
        projection = raw.locator_projection
        if (
            not isinstance(projection, LegacyPageLocatorProjection)
            or projection.actor_subject_id != owner
            or projection.owner_subject_id != owner
            or projection.page_id != proof.page_id
        ):
            raise ValueError("owner-canonical structural locator projection required")
        page_id = proof.page_id
        if page_id in pages:
            raise ValueError("duplicate structural effect page")
        pages.add(page_id)
        effect_old_parent = (
            _source_page_identifier(raw.old_parent_source_page_id)
            if raw.old_parent_source_page_id
            else ""
        )
        effect_new_parent = (
            _source_page_identifier(raw.new_parent_source_page_id)
            if raw.new_parent_source_page_id
            else ""
        )
        old_ordinal = (
            None
            if raw.old_sibling_ordinal is None
            else _bounded_integer(
                raw.old_sibling_ordinal, field="old_sibling_ordinal", minimum=1,
                maximum=MAX_PAGE_TREE_SIBLING_NODES,
            )
        )
        old_depth = (
            None
            if raw.old_depth is None
            else _bounded_integer(
                raw.old_depth, field="old_depth", minimum=0,
                maximum=MAX_PAGE_TREE_DEPTH,
            )
        )
        if (old_ordinal is None) != (old_depth is None):
            raise ValueError("structural before-tree evidence must be complete")
        normalized = WorkspacePageLifecycleStructuralEffectCandidate(
            effect_ordinal=ordinal,
            effect_roles=roles,
            source_mutated=raw.source_mutated,
            source_proof=proof,
            source_incarnation=evidence,
            locator_projection=projection,
            old_parent_source_page_id=effect_old_parent,
            new_parent_source_page_id=effect_new_parent,
            old_sibling_ordinal=old_ordinal,
            new_sibling_ordinal=_bounded_integer(
                raw.new_sibling_ordinal, field="new_sibling_ordinal", minimum=1,
                maximum=MAX_PAGE_TREE_SIBLING_NODES,
            ),
            old_depth=old_depth,
            new_depth=_bounded_integer(
                raw.new_depth, field="new_depth", minimum=0,
                maximum=MAX_PAGE_TREE_DEPTH,
            ),
        )
        if normalized != raw:
            raise ValueError("structural effect must be canonical")
        normalized_effects.append(normalized)
        if roles & PAGE_LIFECYCLE_EFFECT_TARGET:
            target_effects.append(normalized)
    if len(target_effects) != 1:
        raise ValueError("exactly one structural target effect required")
    target = target_effects[0]
    if (
        target.old_parent_source_page_id != old_parent
        or target.new_parent_source_page_id != new_parent
        or target.new_sibling_ordinal != value.target_dense_ordinal
        or target.source_incarnation.incarnation_id != value.target_incarnation_id
        or target.source_incarnation.incarnation_generation
        != value.target_incarnation_generation
        or target.source_incarnation.change_generation
        != value.target_change_generation
        or target.source_incarnation.change_mask != value.target_change_mask
        or target.source_incarnation.receipt_sha256
        != value.target_source_receipt_sha256
    ):
        raise ValueError("structural target receipt is inconsistent")
    if action == "create" and (
        target.old_sibling_ordinal is not None
        or target.old_depth is not None
        or not target.source_mutated
    ):
        raise ValueError("structural create target must be a new source page")
    if action != "create" and target.old_sibling_ordinal is None:
        raise ValueError("existing structural target requires before-tree evidence")
    old_scope_count = _bounded_integer(
        value.old_scope_count, field="old_scope_count", minimum=0,
        maximum=MAX_PAGE_TREE_SIBLING_NODES,
    )
    new_scope_count = _bounded_integer(
        value.new_scope_count, field="new_scope_count", minimum=1,
        maximum=MAX_PAGE_TREE_SIBLING_NODES,
    )
    subtree_count = _bounded_integer(
        value.subtree_count, field="subtree_count", minimum=1,
        maximum=MAX_PAGE_TREE_SYNCHRONOUS_SUBTREE_NODES,
    )
    if (
        sum(bool(item.effect_roles & PAGE_LIFECYCLE_EFFECT_OLD_SCOPE)
            for item in normalized_effects) != old_scope_count
        or sum(bool(item.effect_roles & PAGE_LIFECYCLE_EFFECT_NEW_SCOPE)
               for item in normalized_effects) != new_scope_count
        or sum(bool(item.effect_roles & PAGE_LIFECYCLE_EFFECT_SUBTREE)
               for item in normalized_effects) != subtree_count
        or (action == "create" and (old_scope_count != 0 or subtree_count != 1))
    ):
        raise ValueError("structural effect role counts are inconsistent")
    normalized_candidate = WorkspacePageLifecycleStructuralCandidate(
        action=action,
        source_request_sha256=_sha256_digest(
            value.source_request_sha256, field="source_request_sha256"
        ),
        source_operation_receipt_sha256=_sha256_digest(
            value.source_operation_receipt_sha256,
            field="source_operation_receipt_sha256",
        ),
        post_manifest_sha256=_sha256_digest(
            value.post_manifest_sha256, field="post_manifest_sha256"
        ),
        source_changed=True,
        structure_changed=value.structure_changed,
        source_fence=normalized_fence,
        target_incarnation_id=str(value.target_incarnation_id),
        target_incarnation_generation=_bounded_integer(
            value.target_incarnation_generation,
            field="target_incarnation_generation", minimum=1,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        target_change_generation=_bounded_integer(
            value.target_change_generation, field="target_change_generation", minimum=1,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        target_change_mask=_bounded_integer(
            value.target_change_mask, field="target_change_mask", minimum=1,
            maximum=31,
        ),
        target_source_receipt_sha256=_sha256_digest(
            value.target_source_receipt_sha256,
            field="target_source_receipt_sha256",
        ),
        old_parent_source_page_id=old_parent,
        new_parent_source_page_id=new_parent,
        target_dense_ordinal=_bounded_integer(
            value.target_dense_ordinal, field="target_dense_ordinal", minimum=1,
            maximum=new_scope_count,
        ),
        subtree_count=subtree_count,
        old_scope_count=old_scope_count,
        new_scope_count=new_scope_count,
        effects=tuple(normalized_effects),
    )
    if normalized_candidate != value:
        raise ValueError("structural lifecycle candidate must be canonical")
    return normalized_candidate


def _page_lifecycle_command_result(row: sqlite3.Row) -> dict[str, Any]:
    return {
        "contract": "np2c_page_lifecycle_command_v1",
        "command_id": str(row["id"]),
        "action": str(row["action"]),
        "status": str(row["status"]),
        "command_version": int(row["row_version"]),
        "fencing_generation": int(row["fencing_generation"]),
        "lease_expires_at": (
            int(row["lease_expires_at"])
            if row["lease_expires_at"] is not None
            else None
        ),
        "affected_node_count": int(row["affected_node_count"]),
        "file_work_count": int(row["file_work_count"]),
        "failure_code": str(row["failure_code"] or ""),
    }


def _page_lifecycle_finalized_result(row: sqlite3.Row) -> dict[str, Any]:
    return {
        "contract": PAGE_LIFECYCLE_RESULT_CONTRACT,
        "command_id": str(row["id"]),
        "action": str(row["action"]),
        "status": "finalized",
        "request_sha256": str(row["request_sha256"]),
        "source_receipt_sha256": str(row["source_receipt_sha256"]),
        "affected_node_count": int(row["affected_node_count"]),
        "file_work_count": int(row["file_work_count"]),
        "fencing_generation": int(row["fencing_generation"]),
        "command_version": int(row["row_version"]),
    }


def _normalize_page_lifecycle_finalized_result(
    value: object,
) -> dict[str, Any]:
    if not isinstance(value, dict) or set(value) != {
        "contract",
        "command_id",
        "action",
        "status",
        "request_sha256",
        "source_receipt_sha256",
        "affected_node_count",
        "file_work_count",
        "fencing_generation",
        "command_version",
    }:
        raise ValueError("page lifecycle finalized result is invalid")
    command_id = str(value.get("command_id") or "")
    if not re.fullmatch(r"plc_[0-9a-f]{32}", command_id):
        raise ValueError("page lifecycle finalized result is invalid")
    action = str(value.get("action") or "")
    if action not in PAGE_LIFECYCLE_KERNEL_ACTIONS:
        raise ValueError("page lifecycle finalized result is invalid")
    if value.get("contract") != PAGE_LIFECYCLE_RESULT_CONTRACT or value.get(
        "status"
    ) != "finalized":
        raise ValueError("page lifecycle finalized result is invalid")
    normalized = {
        "contract": PAGE_LIFECYCLE_RESULT_CONTRACT,
        "command_id": command_id,
        "action": action,
        "status": "finalized",
        "request_sha256": _sha256_digest(
            value.get("request_sha256"), field="request_sha256"
        ),
        "source_receipt_sha256": _sha256_digest(
            value.get("source_receipt_sha256"), field="source_receipt_sha256"
        ),
        "affected_node_count": _bounded_integer(
            value.get("affected_node_count"),
            field="affected_node_count",
            minimum=0,
            maximum=MAX_PAGE_TREE_SYNCHRONOUS_SUBTREE_NODES,
        ),
        "file_work_count": _bounded_integer(
            value.get("file_work_count"),
            field="file_work_count",
            minimum=0,
            maximum=MAX_FILE_SOURCES_PER_PAGE,
        ),
        "fencing_generation": _bounded_integer(
            value.get("fencing_generation"),
            field="fencing_generation",
            minimum=1,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        "command_version": _bounded_integer(
            value.get("command_version"),
            field="command_version",
            minimum=4,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
    }
    if normalized != value:
        raise ValueError("page lifecycle finalized result is not canonical")
    return normalized


def _page_lifecycle_rename_finalized_result(
    command: sqlite3.Row,
    *,
    changed: bool,
    workspace: sqlite3.Row,
    binding_version: int,
    source_proof: LegacyPageSourceProof,
    source_incarnation: LegacyPageIncarnationEvidence,
    projection_sha256: str,
    file_source_count: int,
    public_source_count: int,
    tree_state: sqlite3.Row,
    previous_tree_state_version: int,
    tree_node_structure_sha256: str,
) -> dict[str, Any]:
    return {
        "contract": PAGE_LIFECYCLE_RENAME_RESULT_CONTRACT,
        "command_id": str(command["id"]),
        "action": str(command["action"]),
        "status": "finalized",
        "request_sha256": str(command["request_sha256"]),
        "source_receipt_sha256": str(command["source_receipt_sha256"]),
        "changed": changed,
        "full_sweep_required": changed,
        "affected_node_count": int(command["affected_node_count"]),
        "file_work_count": int(command["file_work_count"]),
        "fencing_generation": int(command["fencing_generation"]),
        "command_version": int(command["row_version"]),
        "workspace_version": int(workspace["row_version"]),
        "security_epoch": int(workspace["security_epoch"]),
        "previous_binding_version": int(command["expected_binding_version"]),
        "binding_version": binding_version,
        "source_revision": source_proof.revision,
        "source_updated_at": source_proof.updated_at,
        "source_sha256": source_proof.content_sha256,
        "source_incarnation_generation": source_incarnation.incarnation_generation,
        "source_change_generation": source_incarnation.change_generation,
        "source_incarnation_receipt_sha256": source_incarnation.receipt_sha256,
        "projection_sha256": projection_sha256,
        "file_source_count": file_source_count,
        "public_source_count": public_source_count,
        "tree_version": int(tree_state["tree_version"]),
        "previous_tree_state_version": previous_tree_state_version,
        "tree_state_version": int(tree_state["row_version"]),
        "materialization_state": str(tree_state["materialization_state"]),
        "tree_node_structure_sha256": tree_node_structure_sha256,
    }


def _normalize_page_lifecycle_rename_finalized_result(
    value: object,
) -> dict[str, Any]:
    keys = {
        "contract", "command_id", "action", "status", "request_sha256",
        "source_receipt_sha256", "changed", "full_sweep_required",
        "affected_node_count", "file_work_count", "fencing_generation",
        "command_version", "workspace_version", "security_epoch",
        "previous_binding_version", "binding_version", "source_revision",
        "source_updated_at", "source_sha256", "source_incarnation_generation",
        "source_change_generation", "source_incarnation_receipt_sha256",
        "projection_sha256", "file_source_count", "public_source_count",
        "tree_version", "previous_tree_state_version", "tree_state_version",
        "materialization_state", "tree_node_structure_sha256",
    }
    if not isinstance(value, dict) or set(value) != keys:
        raise ValueError("page lifecycle rename result is invalid")
    if value.get("contract") != PAGE_LIFECYCLE_RENAME_RESULT_CONTRACT:
        raise ValueError("page lifecycle rename result is invalid")
    command_id = str(value.get("command_id") or "")
    if re.fullmatch(r"plc_[0-9a-f]{32}", command_id) is None:
        raise ValueError("page lifecycle rename result is invalid")
    if value.get("action") != "rename" or value.get("status") != "finalized":
        raise ValueError("page lifecycle rename result is invalid")
    if type(value.get("changed")) is not bool or type(
        value.get("full_sweep_required")
    ) is not bool:
        raise ValueError("page lifecycle rename result is invalid")
    changed = bool(value["changed"])
    if bool(value["full_sweep_required"]) != changed:
        raise ValueError("page lifecycle rename result is invalid")
    previous_binding = _bounded_integer(
        value.get("previous_binding_version"),
        field="previous_binding_version", minimum=1,
        maximum=MAX_HEALING_SEQUENCE_VALUE - 1,
    )
    binding_version = _bounded_integer(
        value.get("binding_version"), field="binding_version", minimum=1,
        maximum=MAX_HEALING_SEQUENCE_VALUE,
    )
    if binding_version != previous_binding + (1 if changed else 0):
        raise ValueError("page lifecycle rename result is invalid")
    previous_tree_state = _bounded_integer(
        value.get("previous_tree_state_version"),
        field="previous_tree_state_version", minimum=1,
        maximum=MAX_HEALING_SEQUENCE_VALUE - (1 if changed else 0),
    )
    tree_state_version = _bounded_integer(
        value.get("tree_state_version"), field="tree_state_version", minimum=1,
        maximum=MAX_HEALING_SEQUENCE_VALUE,
    )
    expected_state = "partial" if changed else "complete"
    if (
        tree_state_version != previous_tree_state + (1 if changed else 0)
        or value.get("materialization_state") != expected_state
    ):
        raise ValueError("page lifecycle rename result is invalid")
    normalized = {
        "contract": PAGE_LIFECYCLE_RENAME_RESULT_CONTRACT,
        "command_id": command_id,
        "action": "rename",
        "status": "finalized",
        "request_sha256": _sha256_digest(value.get("request_sha256"), field="request_sha256"),
        "source_receipt_sha256": _sha256_digest(value.get("source_receipt_sha256"), field="source_receipt_sha256"),
        "changed": changed,
        "full_sweep_required": changed,
        "affected_node_count": _bounded_integer(value.get("affected_node_count"), field="affected_node_count", minimum=0, maximum=MAX_PAGE_TREE_SYNCHRONOUS_SUBTREE_NODES),
        "file_work_count": _bounded_integer(value.get("file_work_count"), field="file_work_count", minimum=0, maximum=MAX_FILE_SOURCES_PER_PAGE),
        "fencing_generation": _bounded_integer(value.get("fencing_generation"), field="fencing_generation", minimum=1, maximum=MAX_HEALING_SEQUENCE_VALUE),
        "command_version": _bounded_integer(value.get("command_version"), field="command_version", minimum=4, maximum=MAX_HEALING_SEQUENCE_VALUE),
        "workspace_version": _bounded_integer(value.get("workspace_version"), field="workspace_version", minimum=1, maximum=MAX_HEALING_SEQUENCE_VALUE),
        "security_epoch": _bounded_integer(value.get("security_epoch"), field="security_epoch", minimum=1, maximum=MAX_HEALING_SEQUENCE_VALUE),
        "previous_binding_version": previous_binding,
        "binding_version": binding_version,
        "source_revision": _bounded_integer(value.get("source_revision"), field="source_revision", minimum=1, maximum=MAX_HEALING_SEQUENCE_VALUE),
        "source_updated_at": _bounded_integer(value.get("source_updated_at"), field="source_updated_at", minimum=0, maximum=MAX_HEALING_TIMESTAMP),
        "source_sha256": _sha256_digest(value.get("source_sha256"), field="source_sha256"),
        "source_incarnation_generation": _bounded_integer(value.get("source_incarnation_generation"), field="source_incarnation_generation", minimum=1, maximum=MAX_HEALING_SEQUENCE_VALUE),
        "source_change_generation": _bounded_integer(value.get("source_change_generation"), field="source_change_generation", minimum=1, maximum=MAX_HEALING_SEQUENCE_VALUE),
        "source_incarnation_receipt_sha256": _sha256_digest(value.get("source_incarnation_receipt_sha256"), field="source_incarnation_receipt_sha256"),
        "projection_sha256": _sha256_digest(value.get("projection_sha256"), field="projection_sha256"),
        "file_source_count": _bounded_integer(value.get("file_source_count"), field="file_source_count", minimum=0, maximum=MAX_FILE_SOURCES_PER_PAGE),
        "public_source_count": _bounded_integer(value.get("public_source_count"), field="public_source_count", minimum=0, maximum=MAX_PUBLIC_SOURCES_PER_PAGE),
        "tree_version": _bounded_integer(value.get("tree_version"), field="tree_version", minimum=1, maximum=MAX_HEALING_SEQUENCE_VALUE),
        "previous_tree_state_version": previous_tree_state,
        "tree_state_version": tree_state_version,
        "materialization_state": expected_state,
        "tree_node_structure_sha256": _sha256_digest(
            value.get("tree_node_structure_sha256"),
            field="tree_node_structure_sha256",
        ),
    }
    if normalized != value:
        raise ValueError("page lifecycle rename result is not canonical")
    return normalized


_PAGE_LIFECYCLE_STRUCTURAL_EFFECT_FIELDS = (
    "command_id", "effect_ordinal", "workspace_id",
    "source_owner_subject_id", "source_page_id", "effect_roles",
    "before_binding_version", "after_binding_version",
    "before_source_revision", "after_source_revision",
    "before_source_updated_at", "after_source_updated_at",
    "before_incarnation_id", "before_incarnation_generation",
    "after_incarnation_id", "after_incarnation_generation",
    "before_change_generation", "after_change_generation",
    "before_source_receipt_sha256", "after_source_receipt_sha256",
    "before_page_sha256", "after_page_sha256",
    "before_locator_sha256", "after_locator_sha256",
    "old_parent_source_page_id", "new_parent_source_page_id",
    "old_sibling_ordinal", "new_sibling_ordinal",
    "old_depth", "new_depth", "source_mutated", "created_at",
)


def _page_lifecycle_structural_effect_descriptor(
    value: sqlite3.Row | dict[str, Any],
) -> dict[str, Any]:
    raw = dict(value)
    if not set(_PAGE_LIFECYCLE_STRUCTURAL_EFFECT_FIELDS).issubset(raw):
        raise ValueError("structural lifecycle effect is incomplete")
    return {
        key: (
            None
            if raw[key] is None
            else int(raw[key])
            if key in {
                "effect_ordinal", "effect_roles", "before_binding_version",
                "after_binding_version", "before_source_revision",
                "after_source_revision", "before_source_updated_at",
                "after_source_updated_at", "before_incarnation_generation",
                "after_incarnation_generation", "before_change_generation",
                "after_change_generation", "old_sibling_ordinal",
                "new_sibling_ordinal", "old_depth", "new_depth",
                "source_mutated", "created_at",
            }
            else str(raw[key])
        )
        for key in _PAGE_LIFECYCLE_STRUCTURAL_EFFECT_FIELDS
    }


def _page_lifecycle_structural_effect_set_sha256(
    rows: list[sqlite3.Row] | tuple[sqlite3.Row, ...],
) -> str:
    effects = [
        _page_lifecycle_structural_effect_descriptor(row)
        for row in sorted(rows, key=lambda item: int(item["effect_ordinal"]))
    ]
    return "sha256:" + hashlib.sha256(
        _canonical_json(
            {
                "domain": PAGE_LIFECYCLE_STRUCTURAL_EFFECT_SET_DOMAIN,
                "effects": effects,
            }
        ).encode("utf-8")
    ).hexdigest()


def _normalize_page_lifecycle_structural_finalized_result(
    value: object,
) -> dict[str, Any]:
    keys = {
        "contract", "command_id", "action", "status",
        "catalog_request_sha256", "source_request_sha256",
        "source_receipt_sha256", "post_manifest_sha256", "source_changed",
        "structure_changed", "full_sweep_required", "affected_page_count",
        "source_mutated_page_count", "subtree_count", "old_scope_count",
        "new_scope_count", "order_generation", "structural_effects_sha256",
        "fencing_generation", "command_version", "workspace_version",
        "security_epoch", "previous_tree_version", "tree_version",
        "previous_tree_state_version", "tree_state_version",
        "materialization_state",
    }
    if not isinstance(value, dict) or set(value) != keys:
        raise ValueError("page lifecycle structural result is invalid")
    command_id = str(value.get("command_id") or "")
    if re.fullmatch(r"plc_[0-9a-f]{32}", command_id) is None:
        raise ValueError("page lifecycle structural result is invalid")
    action = str(value.get("action") or "")
    if action not in {"create", "move", "reorder"}:
        raise ValueError("page lifecycle structural result is invalid")
    if (
        value.get("contract") != PAGE_LIFECYCLE_STRUCTURAL_RESULT_CONTRACT
        or value.get("status") != "finalized"
        or type(value.get("source_changed")) is not bool
        or value.get("source_changed") is not True
        or type(value.get("structure_changed")) is not bool
        or type(value.get("full_sweep_required")) is not bool
        or value.get("full_sweep_required") is not True
        or value.get("materialization_state") != "partial"
    ):
        raise ValueError("page lifecycle structural result is invalid")
    structure_changed = bool(value["structure_changed"])
    if action in {"create", "move"} and not structure_changed:
        raise ValueError("page lifecycle structural result is invalid")
    previous_tree_version = _bounded_integer(
        value.get("previous_tree_version"), field="previous_tree_version",
        minimum=1, maximum=MAX_HEALING_SEQUENCE_VALUE - int(structure_changed),
    )
    tree_version = _bounded_integer(
        value.get("tree_version"), field="tree_version", minimum=1,
        maximum=MAX_HEALING_SEQUENCE_VALUE,
    )
    previous_tree_state_version = _bounded_integer(
        value.get("previous_tree_state_version"),
        field="previous_tree_state_version", minimum=1,
        maximum=MAX_HEALING_SEQUENCE_VALUE - 1,
    )
    tree_state_version = _bounded_integer(
        value.get("tree_state_version"), field="tree_state_version", minimum=2,
        maximum=MAX_HEALING_SEQUENCE_VALUE,
    )
    if (
        tree_version != previous_tree_version + int(structure_changed)
        or tree_state_version != previous_tree_state_version + 1
    ):
        raise ValueError("page lifecycle structural result is invalid")
    affected_page_count = _bounded_integer(
        value.get("affected_page_count"), field="affected_page_count",
        minimum=1, maximum=MAX_PAGE_LIFECYCLE_STRUCTURAL_EFFECTS,
    )
    source_mutated_page_count = _bounded_integer(
        value.get("source_mutated_page_count"),
        field="source_mutated_page_count", minimum=1,
        maximum=affected_page_count,
    )
    normalized = {
        "contract": PAGE_LIFECYCLE_STRUCTURAL_RESULT_CONTRACT,
        "command_id": command_id,
        "action": action,
        "status": "finalized",
        "catalog_request_sha256": _sha256_digest(
            value.get("catalog_request_sha256"),
            field="catalog_request_sha256",
        ),
        "source_request_sha256": _sha256_digest(
            value.get("source_request_sha256"),
            field="source_request_sha256",
        ),
        "source_receipt_sha256": _sha256_digest(
            value.get("source_receipt_sha256"), field="source_receipt_sha256"
        ),
        "post_manifest_sha256": _sha256_digest(
            value.get("post_manifest_sha256"), field="post_manifest_sha256"
        ),
        "source_changed": True,
        "structure_changed": structure_changed,
        "full_sweep_required": True,
        "affected_page_count": affected_page_count,
        "source_mutated_page_count": source_mutated_page_count,
        "subtree_count": _bounded_integer(
            value.get("subtree_count"), field="subtree_count", minimum=1,
            maximum=MAX_PAGE_TREE_SYNCHRONOUS_SUBTREE_NODES,
        ),
        "old_scope_count": _bounded_integer(
            value.get("old_scope_count"), field="old_scope_count", minimum=0,
            maximum=MAX_PAGE_TREE_SIBLING_NODES,
        ),
        "new_scope_count": _bounded_integer(
            value.get("new_scope_count"), field="new_scope_count", minimum=1,
            maximum=MAX_PAGE_TREE_SIBLING_NODES,
        ),
        "order_generation": _bounded_integer(
            value.get("order_generation"), field="order_generation", minimum=1,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        "structural_effects_sha256": _sha256_digest(
            value.get("structural_effects_sha256"),
            field="structural_effects_sha256",
        ),
        "fencing_generation": _bounded_integer(
            value.get("fencing_generation"), field="fencing_generation",
            minimum=1, maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        "command_version": _bounded_integer(
            value.get("command_version"), field="command_version", minimum=4,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        "workspace_version": _bounded_integer(
            value.get("workspace_version"), field="workspace_version", minimum=2,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        "security_epoch": _bounded_integer(
            value.get("security_epoch"), field="security_epoch", minimum=2,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        "previous_tree_version": previous_tree_version,
        "tree_version": tree_version,
        "previous_tree_state_version": previous_tree_state_version,
        "tree_state_version": tree_state_version,
        "materialization_state": "partial",
    }
    if normalized != value:
        raise ValueError("page lifecycle structural result is not canonical")
    return normalized


def _normalize_page_lifecycle_subtree_finalized_result(
    value: object,
) -> dict[str, Any]:
    keys = {
        "contract", "command_id", "action", "canonical_action", "status",
        "workspace_id", "source_owner_subject_id", "root_source_page_id",
        "result_root_source_page_id", "catalog_request_sha256",
        "source_request_sha256",
        "source_operation_receipt_sha256", "post_manifest_sha256",
        "file_manifest_sha256", "effect_count", "transitioned_count",
        "mapping_count", "file_mapping_count", "aggregate_file_bytes",
        "order_generation", "fencing_generation", "command_version",
        "workspace_version", "security_epoch", "tree_version",
        "previous_tree_state_version", "tree_state_version",
        "active_node_count", "archived_node_count", "changed",
        "full_sweep_required",
    }
    if not isinstance(value, dict) or set(value) != keys:
        raise ValueError("page lifecycle subtree result is invalid")
    command_id = str(value.get("command_id") or "")
    if re.fullmatch(r"plc_[0-9a-f]{32}", command_id) is None:
        raise ValueError("page lifecycle subtree result is invalid")
    action = str(value.get("action") or "")
    canonical_action = str(value.get("canonical_action") or "")
    if (
        value.get("contract") != PAGE_LIFECYCLE_SUBTREE_RESULT_CONTRACT
        or value.get("status") != "finalized"
        or PAGE_LIFECYCLE_SUBTREE_ACTION_MAP.get(action) != canonical_action
        or type(value.get("changed")) is not bool
        or value.get("changed") is not True
        or type(value.get("full_sweep_required")) is not bool
        or value.get("full_sweep_required") is not True
    ):
        raise ValueError("page lifecycle subtree result is invalid")
    effect_count = _bounded_integer(
        value.get("effect_count"), field="effect_count", minimum=1,
        maximum=MAX_PAGE_LIFECYCLE_SUBTREE_EFFECTS,
    )
    transitioned_count = _bounded_integer(
        value.get("transitioned_count"), field="transitioned_count", minimum=1,
        maximum=MAX_PAGE_TREE_SYNCHRONOUS_SUBTREE_NODES,
    )
    mapping_count = _bounded_integer(
        value.get("mapping_count"), field="mapping_count", minimum=0,
        maximum=MAX_PAGE_LIFECYCLE_SUBTREE_MAPPINGS,
    )
    file_mapping_count = _bounded_integer(
        value.get("file_mapping_count"), field="file_mapping_count", minimum=0,
        maximum=MAX_FILE_SOURCES_PER_PAGE,
    )
    if transitioned_count > effect_count or file_mapping_count > mapping_count:
        raise ValueError("page lifecycle subtree result is invalid")
    normalized = {
        "contract": PAGE_LIFECYCLE_SUBTREE_RESULT_CONTRACT,
        "command_id": command_id,
        "action": action,
        "canonical_action": canonical_action,
        "status": "finalized",
        "workspace_id": _identifier(
            value.get("workspace_id"), prefix="ws", field="workspace_id"
        ),
        "source_owner_subject_id": _subject(
            value.get("source_owner_subject_id"),
            field="source_owner_subject_id",
        ),
        "root_source_page_id": _source_page_identifier(
            value.get("root_source_page_id")
        ),
        "result_root_source_page_id": _source_page_identifier(
            value.get("result_root_source_page_id")
        ),
        "catalog_request_sha256": _sha256_digest(
            value.get("catalog_request_sha256"), field="catalog_request_sha256"
        ),
        "source_request_sha256": _sha256_digest(
            value.get("source_request_sha256"), field="source_request_sha256"
        ),
        "source_operation_receipt_sha256": _sha256_digest(
            value.get("source_operation_receipt_sha256"),
            field="source_operation_receipt_sha256",
        ),
        "post_manifest_sha256": _sha256_digest(
            value.get("post_manifest_sha256"), field="post_manifest_sha256"
        ),
        "file_manifest_sha256": _sha256_digest(
            value.get("file_manifest_sha256"), field="file_manifest_sha256"
        ),
        "effect_count": effect_count,
        "transitioned_count": transitioned_count,
        "mapping_count": mapping_count,
        "file_mapping_count": file_mapping_count,
        "aggregate_file_bytes": _bounded_integer(
            value.get("aggregate_file_bytes"), field="aggregate_file_bytes",
            minimum=0, maximum=MAX_PAGE_LIFECYCLE_AGGREGATE_FILE_BYTES,
        ),
        "order_generation": _bounded_integer(
            value.get("order_generation"), field="order_generation", minimum=1,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        "fencing_generation": _bounded_integer(
            value.get("fencing_generation"), field="fencing_generation", minimum=1,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        "command_version": _bounded_integer(
            value.get("command_version"), field="command_version", minimum=4,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        "workspace_version": _bounded_integer(
            value.get("workspace_version"), field="workspace_version", minimum=1,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        "security_epoch": _bounded_integer(
            value.get("security_epoch"), field="security_epoch", minimum=1,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        "tree_version": _bounded_integer(
            value.get("tree_version"), field="tree_version", minimum=1,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        "previous_tree_state_version": _bounded_integer(
            value.get("previous_tree_state_version"),
            field="previous_tree_state_version", minimum=1,
            maximum=MAX_HEALING_SEQUENCE_VALUE - 1,
        ),
        "tree_state_version": _bounded_integer(
            value.get("tree_state_version"), field="tree_state_version", minimum=2,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        "active_node_count": _bounded_integer(
            value.get("active_node_count"), field="active_node_count", minimum=0,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        "archived_node_count": _bounded_integer(
            value.get("archived_node_count"), field="archived_node_count", minimum=0,
            maximum=MAX_HEALING_SEQUENCE_VALUE,
        ),
        "changed": True,
        "full_sweep_required": True,
    }
    if (
        normalized["tree_state_version"]
        != normalized["previous_tree_state_version"] + 1
        or normalized != value
    ):
        raise ValueError("page lifecycle subtree result is not canonical")
    return normalized


def _validate_page_lifecycle_finalized_commitment_on_connection(
    con: sqlite3.Connection,
    operation: sqlite3.Row,
    parsed_result: object,
    *,
    actor_subject_id: str,
    operation_id: str,
    workspace_id: str,
) -> dict[str, Any]:
    if (
        isinstance(parsed_result, dict)
        and parsed_result.get("contract") == PAGE_LIFECYCLE_RENAME_RESULT_CONTRACT
    ):
        return _validate_page_lifecycle_rename_commitment_on_connection(
            con,
            operation,
            parsed_result,
            actor_subject_id=actor_subject_id,
            operation_id=operation_id,
            workspace_id=workspace_id,
        )
    if (
        isinstance(parsed_result, dict)
        and parsed_result.get("contract")
        == PAGE_LIFECYCLE_STRUCTURAL_RESULT_CONTRACT
    ):
        return _validate_page_lifecycle_structural_commitment_on_connection(
            con,
            operation,
            parsed_result,
            actor_subject_id=actor_subject_id,
            operation_id=operation_id,
            workspace_id=workspace_id,
        )
    if (
        isinstance(parsed_result, dict)
        and parsed_result.get("contract") == PAGE_LIFECYCLE_SUBTREE_RESULT_CONTRACT
    ):
        return _validate_page_lifecycle_subtree_commitment_on_connection(
            con,
            operation,
            parsed_result,
            actor_subject_id=actor_subject_id,
            operation_id=operation_id,
            workspace_id=workspace_id,
        )
    if SCHEMA_VERSION >= 2026081313:
        raise WorkspaceSubstrateUnavailable(
            "legacy workspace page lifecycle finalization is disabled"
        )
    try:
        result = _normalize_page_lifecycle_finalized_result(parsed_result)
        command = con.execute(
            "SELECT * FROM workspace_page_lifecycle_commands WHERE id=?",
            (result["command_id"],),
        ).fetchone()
        if (
            command is None
            or str(command["workspace_id"]) != workspace_id
            or str(command["actor_subject_id"]) != actor_subject_id
            or str(command["operation_id"]) != operation_id
            or _page_lifecycle_finalized_result(command) != result
            or str(operation["actor_subject_id"]) != actor_subject_id
            or str(operation["operation_id"]) != operation_id
            or str(operation["action"]) != PAGE_LIFECYCLE_FINALIZED_ACTION
            or str(operation["workspace_id"]) != workspace_id
            or str(operation["result_json"]) != _canonical_json(result)
            or WorkspaceStore._ledger_authorization(operation)
            != WorkspaceStore._authorization("workspace.admin", workspace_id)
        ):
            raise ValueError
        audits = con.execute(
            "SELECT * FROM workspace_audit_events "
            "WHERE actor_subject_id=? AND operation_id=?",
            (actor_subject_id, operation_id),
        ).fetchall()
        events = con.execute(
            "SELECT * FROM workspace_outbox "
            "WHERE actor_subject_id=? AND operation_id=?",
            (actor_subject_id, operation_id),
        ).fetchall()
        payload = _canonical_json(result)
        if len(audits) != 1 or len(events) != 1:
            raise ValueError
        audit, event = audits[0], events[0]
        if (
            str(audit["workspace_id"]) != workspace_id
            or str(event["workspace_id"]) != workspace_id
            or str(audit["action"]) != PAGE_LIFECYCLE_FINALIZED_ACTION
            or str(event["event_type"]) != PAGE_LIFECYCLE_FINALIZED_ACTION
            or str(audit["target_type"]) != "workspace_page_lifecycle_command"
            or str(event["aggregate_type"]) != "workspace_page_lifecycle_command"
            or str(audit["target_id"]) != result["command_id"]
            or str(event["aggregate_id"]) != result["command_id"]
            or str(audit["payload_json"]) != payload
            or str(event["payload_json"]) != payload
        ):
            raise ValueError
        return result
    except (KeyError, TypeError, ValueError, WorkspaceSubstrateUnavailable) as exc:
        raise WorkspaceSubstrateUnavailable(
            "workspace page lifecycle operation ledger is invalid"
        ) from exc


