    def _change_group_member(
        self,
        actor_subject_id: str | None,
        workspace_id: str,
        group_id: str,
        target_subject_id: str | None,
        *,
        target_active: bool,
        base_version: int,
        operation_id: str,
        remove: bool,
    ) -> dict[str, Any]:
        actor = _subject(actor_subject_id, field="actor_subject_id")
        target = _subject(target_subject_id, field="target_subject_id")
        ws_id = _identifier(workspace_id, prefix="ws", field="workspace_id")
        grp_id = _identifier(group_id, prefix="grp", field="group_id")
        request = {
            "workspace_id": ws_id,
            "group_id": grp_id,
            "target_subject_id": target,
            "remove": remove,
            "base_version": _expected_version(base_version),
        }
        action = "workspace.group_member_removed" if remove else "workspace.group_member_set"

        def handler(con: sqlite3.Connection) -> _MutationEffect:
            self._require_member(con, ws_id, actor, roles=WORKSPACE_ADMIN_ROLES)
            self._assert_version(con, ws_id, base_version)
            if not remove and not target_active:
                raise ValueError("active target_subject_id required")
            group = con.execute(
                "SELECT * FROM workspace_groups WHERE workspace_id=? AND id=?",
                (ws_id, grp_id),
            ).fetchone()
            if not group:
                raise FileNotFoundError("workspace group not found")
            if not self._membership(con, ws_id, target):
                raise ValueError("groups may contain active workspace members only")
            existing = con.execute(
                "SELECT 1 FROM workspace_group_members WHERE group_id=? AND subject_id=?",
                (grp_id, target),
            ).fetchone()
            if remove:
                if not existing:
                    raise FileNotFoundError("group member not found")
                con.execute(
                    "DELETE FROM workspace_group_members WHERE group_id=? AND subject_id=?",
                    (grp_id, target),
                )
            elif not existing:
                con.execute(
                    """
                    INSERT INTO workspace_group_members(
                      group_id,workspace_id,subject_id,added_by_subject_id,created_at
                    ) VALUES(?,?,?,?,?)
                    """,
                    (grp_id, ws_id, target, actor, _now()),
                )
            workspace = self._bump_workspace(con, ws_id, security_change=True)
            member_ids = [
                str(row["subject_id"])
                for row in con.execute(
                    """
                    SELECT subject_id FROM workspace_group_members
                    WHERE group_id=? ORDER BY subject_id
                    """,
                    (grp_id,),
                ).fetchall()
            ]
            return _MutationEffect(
                result={
                    "workspace": self._workspace_public(workspace),
                    "group": {
                        "id": grp_id,
                        "name": str(group["name"]),
                        "member_subject_ids": member_ids,
                    },
                },
                workspace_id=ws_id,
                target_type="workspace_group_member",
                target_id=f"{grp_id}:{target}",
                event_payload={
                    "group_id": grp_id,
                    "subject_id": target,
                    "removed": remove,
                },
                authorization=self._authorization("workspace.admin", ws_id),
            )

        def authorize_replay(con: sqlite3.Connection, _previous: sqlite3.Row) -> None:
            self._require_workspace_admin(con, ws_id, actor)

        return self._mutate(
            actor_subject_id=actor,
            operation_id=operation_id,
            action=action,
            request=request,
            handler=handler,
            replay_authorizer=authorize_replay,
        )

    def create_teamspace(
        self,
        actor_subject_id: str | None,
        workspace_id: str,
        *,
        name: str,
        visibility: str,
        base_version: int,
        operation_id: str,
    ) -> dict[str, Any]:
        actor = _subject(actor_subject_id, field="actor_subject_id")
        ws_id = _identifier(workspace_id, prefix="ws", field="workspace_id")
        clean_name = _name(name)
        normalized_visibility = str(visibility or "").strip().lower()
        if normalized_visibility not in TEAMSPACE_VISIBILITIES:
            raise ValueError("invalid teamspace visibility")
        request = {
            "workspace_id": ws_id,
            "name": clean_name,
            "visibility": normalized_visibility,
            "base_version": _expected_version(base_version),
        }

        def handler(con: sqlite3.Connection) -> _MutationEffect:
            self._require_teamspace_creator(con, ws_id, actor)
            workspace_before = self._assert_version(con, ws_id, base_version)
            teamspace_id = _new_id("ts")
            now = _now()
            try:
                con.execute(
                    """
                    INSERT INTO teamspaces(
                      id,workspace_id,name,name_key,visibility,created_by_subject_id,
                      row_version,created_at,updated_at,archived_at
                    ) VALUES(?,?,?,?,?,?,1,?,?,NULL)
                    """,
                    (
                        teamspace_id,
                        ws_id,
                        clean_name,
                        clean_name.casefold(),
                        normalized_visibility,
                        actor,
                        now,
                        now,
                    ),
                )
            except sqlite3.IntegrityError as exc:
                raise ValueError("teamspace name already exists") from exc
            con.execute(
                """
                INSERT INTO teamspace_memberships(
                  teamspace_id,workspace_id,subject_id,role,membership_epoch,
                  added_by_subject_id,joined_at,updated_at,revoked_at
                ) VALUES(?,?,?,'owner',1,?,?,?,NULL)
                """,
                (teamspace_id, ws_id, actor, actor, now, now),
            )
            workspace = self._bump_workspace(con, ws_id, security_change=True)
            teamspace_row = con.execute(
                "SELECT * FROM teamspaces WHERE id=?", (teamspace_id,)
            ).fetchone()
            return _MutationEffect(
                result={
                    "workspace": self._workspace_public(workspace),
                    "teamspace": self._teamspace_public(teamspace_row, "owner"),
                },
                workspace_id=ws_id,
                target_type="teamspace",
                target_id=teamspace_id,
                event_payload={
                    "teamspace_id": teamspace_id,
                    "visibility": normalized_visibility,
                },
                authorization=self._authorization(
                    "workspace.teamspace.create", ws_id
                ),
            )

        def authorize_replay(con: sqlite3.Connection, _previous: sqlite3.Row) -> None:
            self._require_teamspace_creator(con, ws_id, actor)

        return self._mutate(
            actor_subject_id=actor,
            operation_id=operation_id,
            action="workspace.teamspace_created",
            request=request,
            handler=handler,
            replay_authorizer=authorize_replay,
        )

