    def _change_teamspace_member(
        self,
        actor_subject_id: str | None,
        workspace_id: str,
        teamspace_id: str,
        target_subject_id: str | None,
        *,
        role: str,
        target_active: bool,
        base_version: int,
        operation_id: str,
        remove: bool,
    ) -> dict[str, Any]:
        actor = _subject(actor_subject_id, field="actor_subject_id")
        target = _subject(target_subject_id, field="target_subject_id")
        ws_id = _identifier(workspace_id, prefix="ws", field="workspace_id")
        ts_id = _identifier(teamspace_id, prefix="ts", field="teamspace_id")
        normalized_role = str(role or "").strip().lower()
        if normalized_role not in TEAMSPACE_ROLES:
            raise ValueError("invalid teamspace role")
        request = {
            "workspace_id": ws_id,
            "teamspace_id": ts_id,
            "target_subject_id": target,
            "role": normalized_role,
            "remove": remove,
            "base_version": _expected_version(base_version),
        }
        action = (
            "workspace.teamspace_member_removed"
            if remove
            else "workspace.teamspace_member_set"
        )

        def handler(con: sqlite3.Connection) -> _MutationEffect:
            _actor_membership, teamspace = self._require_teamspace_manager(
                con,
                ws_id,
                ts_id,
                actor,
                target,
                normalized_role,
                remove=remove,
            )
            actor_teamspace = con.execute(
                """
                SELECT role FROM teamspace_memberships
                WHERE teamspace_id=? AND subject_id=? AND revoked_at IS NULL
                """,
                (ts_id, actor),
            ).fetchone()
            if str(_actor_membership["role"]) in WORKSPACE_ADMIN_ROLES:
                required_capability = "workspace.admin"
            elif actor_teamspace and str(actor_teamspace["role"]) == "owner":
                required_capability = "teamspace.owner"
            else:
                required_capability = "teamspace.self_join_open"
            self._assert_version(con, ws_id, base_version)
            if not remove and not target_active:
                raise ValueError("active target_subject_id required")
            target_membership = self._membership(con, ws_id, target)
            if not target_membership:
                raise ValueError("teamspaces may contain active workspace members only")
            existing = con.execute(
                "SELECT * FROM teamspace_memberships WHERE teamspace_id=? AND subject_id=?",
                (ts_id, target),
            ).fetchone()
            now = _now()
            if remove:
                if not existing or existing["revoked_at"] is not None:
                    raise FileNotFoundError("teamspace member not found")
                if str(existing["role"]) == "owner":
                    owner_count = int(
                        con.execute(
                            """
                            SELECT COUNT(*) FROM teamspace_memberships
                            WHERE teamspace_id=? AND role='owner' AND revoked_at IS NULL
                            """,
                            (ts_id,),
                        ).fetchone()[0]
                    )
                    if owner_count <= 1:
                        raise ValueError("teamspace must retain at least one owner")
                con.execute(
                    """
                    UPDATE workspace_page_sources
                    SET state='quarantined',quarantined_at=?,
                        quarantine_reason='catalog_permission_revoked',
                        quarantine_source_generation=row_version+1,
                        row_version=row_version+1,updated_at=?
                    WHERE workspace_id=? AND teamspace_id=?
                      AND source_owner_subject_id=?
                      AND state IN ('pending','active')
                    """,
                    (now, now, ws_id, ts_id, target),
                )
                con.execute(
                    """
                    UPDATE teamspace_memberships
                    SET revoked_at=?,updated_at=?,membership_epoch=membership_epoch+1
                    WHERE teamspace_id=? AND subject_id=? AND revoked_at IS NULL
                    """,
                    (now, now, ts_id, target),
                )
                member_result = {"subject_id": target, "revoked": True}
            else:
                if (
                    existing
                    and existing["revoked_at"] is None
                    and str(existing["role"]) == "owner"
                    and normalized_role != "owner"
                ):
                    owner_count = int(
                        con.execute(
                            """
                            SELECT COUNT(*) FROM teamspace_memberships
                            WHERE teamspace_id=? AND role='owner' AND revoked_at IS NULL
                            """,
                            (ts_id,),
                        ).fetchone()[0]
                    )
                    if owner_count <= 1:
                        raise ValueError("teamspace must retain at least one owner")
                next_epoch = int(existing["membership_epoch"] if existing else 0) + 1
                con.execute(
                    """
                    INSERT INTO teamspace_memberships(
                      teamspace_id,workspace_id,subject_id,role,membership_epoch,
                      added_by_subject_id,joined_at,updated_at,revoked_at
                    ) VALUES(?,?,?,?,?,?,?,?,NULL)
                    ON CONFLICT(teamspace_id,subject_id) DO UPDATE SET
                      role=excluded.role,
                      membership_epoch=excluded.membership_epoch,
                      added_by_subject_id=excluded.added_by_subject_id,
                      updated_at=excluded.updated_at,
                      revoked_at=NULL
                    """,
                    (ts_id, ws_id, target, normalized_role, next_epoch, actor, now, now),
                )
                member_result = {
                    "subject_id": target,
                    "role": normalized_role,
                    "membership_epoch": next_epoch,
                }
            con.execute(
                "UPDATE teamspaces SET row_version=row_version+1,updated_at=? WHERE id=?",
                (now, ts_id),
            )
            workspace = self._bump_workspace(con, ws_id, security_change=True)
            return _MutationEffect(
                result={
                    "workspace": self._workspace_public(workspace),
                    "teamspace_member": member_result,
                },
                workspace_id=ws_id,
                target_type="teamspace_member",
                target_id=f"{ts_id}:{target}",
                event_payload={
                    "teamspace_id": ts_id,
                    "subject_id": target,
                    "role": normalized_role,
                    "removed": remove,
                },
                authorization=self._authorization(
                    required_capability,
                    ws_id,
                    teamspace_id=ts_id,
                    target_subject_id=target,
                    requested_role=normalized_role,
                    remove=remove,
                ),
            )

        def authorize_replay(con: sqlite3.Connection, _previous: sqlite3.Row) -> None:
            self._require_teamspace_manager(
                con,
                ws_id,
                ts_id,
                actor,
                target,
                normalized_role,
                remove=remove,
            )

        return self._mutate(
            actor_subject_id=actor,
            operation_id=operation_id,
            action=action,
            request=request,
            handler=handler,
            replay_authorizer=authorize_replay,
        )

    @staticmethod
    def _derived_operation_id(kind: str, operation_id: str) -> str:
        source = _operation_id(operation_id)
        digest = hashlib.sha256(f"{kind}:{source}".encode("utf-8")).hexdigest()
        return f"internal.{kind}.{digest}"

    @staticmethod
    def _normalize_page_locator_projection(
        actor_subject_id: str | None,
        workspace_id: str,
        projection: LegacyPageLocatorProjection,
    ) -> tuple[str, str, str, str, int, LegacyPageLocatorProjection]:
        actor = _subject(actor_subject_id, field="actor_subject_id")
        ws_id = _identifier(workspace_id, prefix="ws", field="workspace_id")
        if not isinstance(projection, LegacyPageLocatorProjection):
            raise ValueError("LegacyPageLocatorProjection required")
        projection_actor = _subject(
            projection.actor_subject_id,
            field="projection.actor_subject_id",
        )
        if projection_actor != actor or projection.actor_subject_id != actor:
            raise PermissionError("page locator projection actor mismatch")
        owner = _subject(
            projection.owner_subject_id,
            field="projection.owner_subject_id",
        )
        if projection.owner_subject_id != owner:
            raise ValueError("projection.owner_subject_id must be canonical")
        page_id = str(projection.page_id or "")
        if not page_id or page_id != page_id.strip() or len(page_id) > 160:
            raise ValueError("valid projection.page_id required")
        binding_version = _expected_version(projection.binding_version)

        if not isinstance(projection.file_sources, tuple) or not isinstance(
            projection.public_sources, tuple
        ):
            raise ValueError("projection sources must be immutable tuples")
        raw_files = projection.file_sources
        raw_public = projection.public_sources
        if len(raw_files) > MAX_FILE_SOURCES_PER_PAGE:
            raise ValueError("too many file sources in one page projection")
        if len(raw_public) > MAX_PUBLIC_SOURCES_PER_PAGE:
            raise ValueError("too many public sources in one page projection")

        file_sources: list[LegacyFileSourceLocator] = []
        for item in raw_files:
            if not isinstance(item, LegacyFileSourceLocator):
                raise ValueError("LegacyFileSourceLocator required")
            source_file_id = _source_file_id(item.source_file_id)
            file_sources.append(LegacyFileSourceLocator(source_file_id))
        file_ids = [item.source_file_id for item in file_sources]
        if file_ids != sorted(file_ids):
            raise ValueError("file sources must be sorted by source_file_id")
        if len(file_ids) != len(set(file_ids)):
            raise ValueError("duplicate source_file_id in page projection")

        public_sources: list[LegacyPublicSourceLocator] = []
        for item in raw_public:
            if not isinstance(item, LegacyPublicSourceLocator):
                raise ValueError("LegacyPublicSourceLocator required")
            token_sha256 = _sha256_digest(
                item.token_sha256,
                field="public source token_sha256",
            )
            if not isinstance(item.allow_duplicate, bool):
                raise ValueError("public source allow_duplicate must be boolean")
            public_sources.append(
                LegacyPublicSourceLocator(token_sha256, item.allow_duplicate)
            )
        public_hashes = [item.token_sha256 for item in public_sources]
        if public_hashes != sorted(public_hashes):
            raise ValueError("public sources must be sorted by token_sha256")
        if len(public_hashes) != len(set(public_hashes)):
            raise ValueError("duplicate token_sha256 in page projection")

        normalized = LegacyPageLocatorProjection(
            actor_subject_id=actor,
            owner_subject_id=owner,
            page_id=page_id,
            binding_version=binding_version,
            file_sources=tuple(file_sources),
            public_sources=tuple(public_sources),
        )
        return actor, owner, ws_id, page_id, binding_version, normalized

    @classmethod
    def _page_projection_authorization(
        cls,
        con: sqlite3.Connection,
        *,
        actor_subject_id: str,
        workspace_id: str,
        source_owner_subject_id: str,
        source_page_id: str,
        binding_version: int,
    ) -> _AuthorizationRequirement:
        # Prove coarse workspace authority before consulting a binding row.
        # This deliberately makes unknown/stale binding generations
        # indistinguishable to outsiders and prevents workspace-version oracles.
        if actor_subject_id == source_owner_subject_id:
            cls._require_member(con, workspace_id, actor_subject_id)
        else:
            cls._require_workspace_admin(
                con, workspace_id, actor_subject_id
            )
        binding = con.execute(
            """
            SELECT teamspace_id,state,row_version
            FROM workspace_page_sources
            WHERE workspace_id=? AND source_owner_subject_id=? AND source_page_id=?
            """,
            (workspace_id, source_owner_subject_id, source_page_id),
        ).fetchone()
        if (
            not binding
            or str(binding["state"]) != "active"
            or int(binding["row_version"]) != binding_version
        ):
            raise ValueError("active page binding generation is stale")
        authorization = cls._authorization(
            "workspace.page_source.bind_self"
            if actor_subject_id == source_owner_subject_id
            else "workspace.page_source.bind_admin",
            workspace_id,
            source_owner_subject_id=source_owner_subject_id,
            teamspace_id=str(binding["teamspace_id"] or ""),
        )
        cls._authorize_requirement(con, actor_subject_id, authorization)
        return authorization

    def replace_page_locator_projection(
        self,
        actor_subject_id: str | None,
        workspace_id: str,
        projection: LegacyPageLocatorProjection,
        *,
        projection_revalidator: Callable[[LegacyPageLocatorProjection], bool],
        base_version: int,
        operation_id: str,
    ) -> dict[str, Any]:
        """Atomically replace rebuildable locators for one active page generation.

        The external callback receives only a normalized projection containing
        opaque file IDs and public-token digests.  It runs outside the catalog
        transaction.  Current IAM, workspace CAS, and binding generation are
        checked both before and after that call.
        """
        if not callable(projection_revalidator):
            raise ValueError("projection_revalidator required")
        (
            actor,
            owner,
            ws_id,
            page_id,
            binding_version,
            normalized,
        ) = self._normalize_page_locator_projection(
            actor_subject_id,
            workspace_id,
            projection,
        )
        workspace_version = _expected_version(base_version)
        op_id = _operation_id(operation_id)
        action = "workspace.page_locator_projection_replaced"
        request = {
            "workspace_id": ws_id,
            "projection": normalized.descriptor(),
            "base_version": workspace_version,
        }
        request_hash = _request_hash(actor, action, request)
        replayed, replay_result = self._replay_from_ledger(
            actor_subject_id=actor,
            operation_id=op_id,
            action=action,
            request_hash=request_hash,
        )
        if replayed:
            return replay_result

        read_con = self._read_connection()
        try:
            authorization = self._page_projection_authorization(
                read_con,
                actor_subject_id=actor,
                workspace_id=ws_id,
                source_owner_subject_id=owner,
                source_page_id=page_id,
                binding_version=binding_version,
            )
            self._assert_version(read_con, ws_id, workspace_version)
        finally:
            read_con.close()

        if projection_revalidator(normalized) is not True:
            raise ValueError("legacy page locator projection is invalid or stale")

        desired_files = tuple(
            item.source_file_id for item in normalized.file_sources
        )
        desired_public = tuple(
            (item.token_sha256, item.allow_duplicate)
            for item in normalized.public_sources
        )
        desired_projection_sha256 = _page_projection_sha256(
            workspace_id=ws_id,
            source_owner_subject_id=owner,
            source_page_id=page_id,
            binding_version=binding_version,
            file_sources=desired_files,
            public_sources=desired_public,
        )

        def handler(con: sqlite3.Connection) -> _MutationEffect:
            current_authorization = self._page_projection_authorization(
                con,
                actor_subject_id=actor,
                workspace_id=ws_id,
                source_owner_subject_id=owner,
                source_page_id=page_id,
                binding_version=binding_version,
            )
            if current_authorization != authorization:
                raise ValueError("page binding placement changed")
            workspace_before = self._assert_version(
                con, ws_id, workspace_version
            )

            existing_files = tuple(
                str(row["source_file_id"])
                for row in con.execute(
                    """
                    SELECT source_file_id FROM workspace_file_sources
                    WHERE workspace_id=? AND source_owner_subject_id=?
                      AND source_page_id=? AND binding_version=?
                    ORDER BY source_file_id
                    """,
                    (ws_id, owner, page_id, binding_version),
                ).fetchall()
            )
            existing_public = tuple(
                (str(row["token_sha256"]), bool(row["allow_duplicate"]))
                for row in con.execute(
                    """
                    SELECT token_sha256,allow_duplicate
                    FROM workspace_public_sources
                    WHERE workspace_id=? AND source_owner_subject_id=?
                      AND source_page_id=? AND binding_version=?
                    ORDER BY token_sha256
                    """,
                    (ws_id, owner, page_id, binding_version),
                ).fetchall()
            )
            existing_summary = con.execute(
                """
                SELECT projection_sha256,file_source_count,public_source_count
                FROM workspace_page_source_projections
                WHERE workspace_id=? AND source_owner_subject_id=?
                  AND source_page_id=? AND binding_version=?
                """,
                (ws_id, owner, page_id, binding_version),
            ).fetchone()
            changed = (
                not existing_summary
                or str(existing_summary["projection_sha256"])
                != desired_projection_sha256
                or int(existing_summary["file_source_count"])
                != len(desired_files)
                or int(existing_summary["public_source_count"])
                != len(desired_public)
                or existing_files != desired_files
                or existing_public != desired_public
            )
            if changed:
                con.execute(
                    """
                    DELETE FROM workspace_page_source_projections
                    WHERE workspace_id=? AND source_owner_subject_id=?
                      AND source_page_id=?
                    """,
                    (ws_id, owner, page_id),
                )
                now = _now()
                con.execute(
                    """
                    INSERT INTO workspace_page_source_projections(
                      workspace_id,source_owner_subject_id,source_page_id,
                      binding_version,projection_sha256,file_source_count,
                      public_source_count,projected_at
                    ) VALUES(?,?,?,?,?,?,?,?)
                    """,
                    (
                        ws_id,
                        owner,
                        page_id,
                        binding_version,
                        desired_projection_sha256,
                        len(desired_files),
                        len(desired_public),
                        now,
                    ),
                )
                con.executemany(
                    """
                    INSERT INTO workspace_file_sources(
                      workspace_id,source_owner_subject_id,source_page_id,
                      binding_version,source_file_id,created_at
                    ) VALUES(?,?,?,?,?,?)
                    """,
                    [
                        (ws_id, owner, page_id, binding_version, item, now)
                        for item in desired_files
                    ],
                )
                try:
                    con.executemany(
                        """
                        INSERT INTO workspace_public_sources(
                          workspace_id,source_owner_subject_id,source_page_id,
                          binding_version,token_sha256,allow_duplicate,created_at
                        ) VALUES(?,?,?,?,?,?,?)
                        """,
                        [
                            (
                                ws_id,
                                owner,
                                page_id,
                                binding_version,
                                token_sha256,
                                1 if allow_duplicate else 0,
                                now,
                            )
                            for token_sha256, allow_duplicate in desired_public
                        ],
                    )
                except sqlite3.IntegrityError as exc:
                    raise ValueError(
                        "public token digest is already projected"
                    ) from exc
                workspace = self._bump_workspace(
                    con, ws_id, security_change=True
                )
            else:
                workspace = workspace_before

            summary = {
                "workspace_id": ws_id,
                "source_owner_subject_id": owner,
                "source_page_id": page_id,
                "binding_version": binding_version,
                "file_source_count": len(desired_files),
                "public_source_count": len(desired_public),
                "changed": changed,
            }
            return _MutationEffect(
                result={
                    "workspace": self._workspace_public(workspace),
                    "projection": summary,
                },
                workspace_id=ws_id,
                target_type="legacy_page_locator_projection",
                target_id=f"{owner}:{page_id}:{binding_version}",
                event_payload=summary,
                authorization=authorization,
            )

        def authorize_replay(
            con: sqlite3.Connection, _previous: sqlite3.Row
        ) -> None:
            self._authorize_requirement(con, actor, authorization)

        return self._mutate(
            actor_subject_id=actor,
            operation_id=op_id,
            action=action,
            request=request,
            handler=handler,
            replay_authorizer=authorize_replay,
        )

    @classmethod
    def _normalize_page_source(
        cls,
        actor_subject_id: str | None,
        workspace_id: str,
        source_proof: LegacyPageSourceProof,
        teamspace_id: str,
    ) -> tuple[str, str, str, str, str, str, _AuthorizationRequirement]:
        actor = _subject(actor_subject_id, field="actor_subject_id")
        if not isinstance(source_proof, LegacyPageSourceProof):
            raise ValueError("LegacyPageSourceProof required")
        proof_actor = _subject(
            source_proof.actor_subject_id, field="source_proof.actor_subject_id"
        )
        if proof_actor != actor:
            raise PermissionError("legacy page source proof actor mismatch")
        owner = _subject(
            source_proof.owner_subject_id, field="source_proof.owner_subject_id"
        )
        ws_id = _identifier(workspace_id, prefix="ws", field="workspace_id")
        page_id = str(source_proof.page_id or "").strip()
        if not page_id or len(page_id) > 160:
            raise ValueError("valid source proof page_id required")
        if (
            isinstance(source_proof.revision, bool)
            or not isinstance(source_proof.revision, int)
            or source_proof.revision < 1
        ):
            raise ValueError("valid source proof revision required")
        if (
            isinstance(source_proof.updated_at, bool)
            or not isinstance(source_proof.updated_at, int)
            or source_proof.updated_at < 0
        ):
            raise ValueError("valid source proof updated_at required")
        content_sha256 = str(source_proof.content_sha256 or "").strip().lower()
        if not re.fullmatch(r"sha256:[0-9a-f]{64}", content_sha256):
            raise ValueError("valid source proof content_sha256 required")
        ts_id = (
            _identifier(teamspace_id, prefix="ts", field="teamspace_id")
            if str(teamspace_id or "").strip()
            else ""
        )
        placement = "teamspace" if ts_id else "private"
        authorization = cls._authorization(
            "workspace.page_source.bind_self"
            if actor == owner
            else "workspace.page_source.bind_admin",
            ws_id,
            source_owner_subject_id=owner,
            teamspace_id=ts_id,
        )
        return actor, owner, ws_id, page_id, ts_id, placement, authorization

    def stage_page_source_binding(
        self,
        actor_subject_id: str | None,
        workspace_id: str,
        source_proof: LegacyPageSourceProof,
        *,
        teamspace_id: str = "",
        base_version: int,
        operation_id: str,
        expected_catalog_fingerprint: str = "",
    ) -> dict[str, Any]:
        """Durably stage an invisible source candidate before cross-DB validation."""
        (
            actor,
            owner,
            ws_id,
            page_id,
            ts_id,
            placement,
            authorization,
        ) = self._normalize_page_source(
            actor_subject_id, workspace_id, source_proof, teamspace_id
        )
        content_sha256 = str(source_proof.content_sha256).lower()
        request = {
            "workspace_id": ws_id,
            "source_owner_subject_id": owner,
            "source_page_id": page_id,
            "teamspace_id": ts_id,
            "placement": placement,
            "source_proof": source_proof.descriptor(),
            "base_version": _expected_version(base_version),
        }

        def handler(con: sqlite3.Connection) -> _MutationEffect:
            self._authorize_requirement(con, actor, authorization)
            workspace_before = self._assert_version(con, ws_id, base_version)
            existing = con.execute(
                """
                SELECT * FROM workspace_page_sources
                WHERE source_owner_subject_id=? AND source_page_id=?
                """,
                (owner, page_id),
            ).fetchone()
            if existing and str(existing["workspace_id"]) != ws_id:
                raise ValueError("page source is already bound to another workspace")
            now = _now()
            next_version = int(existing["row_version"] if existing else 0) + 1
            con.execute(
                """
                INSERT INTO workspace_page_sources(
                  workspace_id,source_owner_subject_id,source_page_id,teamspace_id,
                  placement,state,quarantined_at,source_revision,source_updated_at,
                  source_sha256,bound_by_subject_id,row_version,created_at,updated_at
                ) VALUES(?,?,?,?,?,'pending',NULL,?,?,?,?,?,?,?)
                ON CONFLICT(workspace_id,source_owner_subject_id,source_page_id) DO UPDATE SET
                  teamspace_id=excluded.teamspace_id,
                  placement=excluded.placement,
                  state='pending',
                  quarantined_at=NULL,
                  quarantine_reason=NULL,
                  quarantine_source_generation=NULL,
                  source_revision=excluded.source_revision,
                  source_updated_at=excluded.source_updated_at,
                  source_sha256=excluded.source_sha256,
                  row_version=excluded.row_version,
                  updated_at=excluded.updated_at
                """,
                (
                    ws_id,
                    owner,
                    page_id,
                    ts_id or None,
                    placement,
                    source_proof.revision,
                    source_proof.updated_at,
                    content_sha256,
                    actor,
                    next_version,
                    now,
                    now,
                ),
            )
            if existing and str(existing["state"]) == "active":
                workspace = self._bump_workspace(
                    con, ws_id, security_change=True
                )
            else:
                workspace = workspace_before
            binding = {
                "workspace_id": ws_id,
                "source_owner_subject_id": owner,
                "source_page_id": page_id,
                "teamspace_id": ts_id,
                "placement": placement,
                "state": "pending",
                "source_revision": source_proof.revision,
                "source_updated_at": source_proof.updated_at,
                "source_sha256": content_sha256,
                "version": next_version,
            }
            return _MutationEffect(
                result={
                    "workspace": self._workspace_public(workspace),
                    "binding": binding,
                },
                workspace_id=ws_id,
                target_type="legacy_page_source_candidate",
                target_id=f"{owner}:{page_id}",
                event_payload=binding,
                authorization=authorization,
            )

        def authorize_replay(con: sqlite3.Connection, _previous: sqlite3.Row) -> None:
            self._authorize_requirement(con, actor, authorization)

        return self._mutate(
            actor_subject_id=actor,
            operation_id=operation_id,
            action="workspace.page_source_staged",
            request=request,
            handler=handler,
            replay_authorizer=authorize_replay,
            expected_database_fingerprint=str(expected_catalog_fingerprint or ""),
        )

    def activate_page_source_binding(
        self,
        actor_subject_id: str | None,
        workspace_id: str,
        source_proof: LegacyPageSourceProof,
        *,
        source_revalidator: Callable[[LegacyPageSourceProof], bool],
        expected_binding_version: int,
        teamspace_id: str = "",
        base_version: int,
        operation_id: str,
        expected_catalog_fingerprint: str = "",
    ) -> dict[str, Any]:
        """Revalidate outside the writer lock, then CAS a pending source active."""
        if not callable(source_revalidator):
            raise ValueError("source_revalidator required")
        (
            actor,
            owner,
            ws_id,
            page_id,
            ts_id,
            placement,
            authorization,
        ) = self._normalize_page_source(
            actor_subject_id, workspace_id, source_proof, teamspace_id
        )
        expected = _expected_version(expected_binding_version)
        workspace_version = _expected_version(base_version)
        op_id = _operation_id(operation_id)
        content_sha256 = str(source_proof.content_sha256).lower()
        request = {
            "workspace_id": ws_id,
            "source_owner_subject_id": owner,
            "source_page_id": page_id,
            "teamspace_id": ts_id,
            "placement": placement,
            "source_proof": source_proof.descriptor(),
            "expected_binding_version": expected,
            "base_version": workspace_version,
        }
        request_hash = _request_hash(actor, "workspace.page_source_bound", request)

        replayed, replay_result = self._replay_from_ledger(
            actor_subject_id=actor,
            operation_id=op_id,
            action="workspace.page_source_bound",
            request_hash=request_hash,
            expected_database_fingerprint=str(expected_catalog_fingerprint or ""),
        )
        if replayed:
            return replay_result

        # Authorize and validate the pending candidate before crossing into the
        # legacy authority.  The same facts are rechecked under the writer lock.
        read_con = self._read_connection()
        try:
            self._authorize_requirement(read_con, actor, authorization)
            self._assert_version(read_con, ws_id, workspace_version)
            candidate = read_con.execute(
                """
                SELECT * FROM workspace_page_sources
                WHERE workspace_id=? AND source_owner_subject_id=? AND source_page_id=?
                """,
                (ws_id, owner, page_id),
            ).fetchone()
            if not candidate or str(candidate["state"]) != "pending" or int(
                candidate["row_version"]
            ) != expected:
                raise ValueError("page source pending binding is stale")
        finally:
            read_con.close()

        # Cross-database work is deliberately outside any catalog transaction.
        if source_revalidator(source_proof) is not True:
            raise ValueError("legacy page source proof is invalid or stale")

        def handler(con: sqlite3.Connection) -> _MutationEffect:
            self._authorize_requirement(con, actor, authorization)
            self._assert_version(con, ws_id, workspace_version)
            now = _now()
            updated = con.execute(
                """
                UPDATE workspace_page_sources
                SET state='active',quarantined_at=NULL,quarantine_reason=NULL,
                    quarantine_source_generation=NULL,updated_at=?
                WHERE workspace_id=? AND source_owner_subject_id=? AND source_page_id=?
                  AND state='pending' AND row_version=? AND placement=?
                  AND COALESCE(teamspace_id,'')=? AND source_revision=?
                  AND source_updated_at=? AND source_sha256=?
                """,
                (
                    now,
                    ws_id,
                    owner,
                    page_id,
                    expected,
                    placement,
                    ts_id,
                    source_proof.revision,
                    source_proof.updated_at,
                    content_sha256,
                ),
            )
            if updated.rowcount != 1:
                raise ValueError("page source pending binding is stale")
            workspace = self._bump_workspace(con, ws_id, security_change=True)
            binding = {
                "workspace_id": ws_id,
                "source_owner_subject_id": owner,
                "source_page_id": page_id,
                "teamspace_id": ts_id,
                "placement": placement,
                "source_revision": source_proof.revision,
                "source_updated_at": source_proof.updated_at,
                "source_sha256": content_sha256,
                # row_version identifies the staged proof generation.  The
                # pending->active CAS consumes that exact generation without
                # manufacturing a second proof version.
                "version": expected,
            }
            return _MutationEffect(
                result={
                    "workspace": self._workspace_public(workspace),
                    "binding": binding,
                },
                workspace_id=ws_id,
                target_type="legacy_page_source",
                target_id=f"{owner}:{page_id}",
                event_payload=binding,
                authorization=authorization,
            )

        def authorize_replay(con: sqlite3.Connection, _previous: sqlite3.Row) -> None:
            self._authorize_requirement(con, actor, authorization)

        return self._mutate(
            actor_subject_id=actor,
            operation_id=op_id,
            action="workspace.page_source_bound",
            request=request,
            handler=handler,
            replay_authorizer=authorize_replay,
            expected_database_fingerprint=str(expected_catalog_fingerprint or ""),
        )

    def get_page_sources_batch_replay(
        self,
        actor_subject_id: str | None,
        workspace_id: str,
        source_page_ids: list[str],
        *,
        operation_id: str,
    ) -> dict[str, Any] | None:
        """Authorize and validate an exact subtree-binding replay."""

        actor = _subject(actor_subject_id, field="actor_subject_id")
        ws_id = _identifier(workspace_id, prefix="ws", field="workspace_id")
        op_id = _operation_id(operation_id)
        if not isinstance(source_page_ids, list) or not source_page_ids:
            raise ValueError("source_page_ids must be a non-empty list")
        normalized_ids = sorted(
            {
                str(page_id or "").strip()
                for page_id in source_page_ids
                if str(page_id or "").strip()
            }
        )
        if len(normalized_ids) != len(source_page_ids) or len(normalized_ids) > MAX_PAGE_SOURCE_BATCH:
            raise ValueError("source_page_ids are invalid")
        authorization = self._authorization(
            "workspace.page_source.bind_self",
            ws_id,
            source_owner_subject_id=actor,
        )
        con = self._read_connection()
        try:
            row = con.execute(
                """
                SELECT * FROM workspace_operations
                WHERE actor_subject_id=? AND operation_id=?
                """,
                (actor, op_id),
            ).fetchone()
            if row is None:
                self._authorize_requirement(con, actor, authorization)
                return None
            if str(row["action"]) != "workspace.page_sources_bound_batch" or str(
                row["workspace_id"]
            ) != ws_id:
                raise WorkspaceOperationConflict(op_id)
            self._authorize_requirement(con, actor, self._ledger_authorization(row))
            try:
                result = json.loads(str(row["result_json"]))
            except json.JSONDecodeError as exc:
                raise WorkspaceSubstrateUnavailable(
                    "workspace page source batch ledger is invalid"
                ) from exc
            if not isinstance(result, dict) or set(result) != {
                "bindings",
                "changed",
                "workspace",
            }:
                raise WorkspaceSubstrateUnavailable(
                    "workspace page source batch ledger is invalid"
                )
            bindings = result.get("bindings")
            if not isinstance(bindings, list) or len(bindings) != len(normalized_ids):
                raise WorkspaceSubstrateUnavailable(
                    "workspace page source batch ledger is invalid"
                )
            observed_ids: list[str] = []
            for binding in bindings:
                if (
                    not isinstance(binding, dict)
                    or str(binding.get("workspace_id") or "") != ws_id
                    or str(binding.get("source_owner_subject_id") or "") != actor
                    or str(binding.get("state") or "") != "active"
                ):
                    raise WorkspaceSubstrateUnavailable(
                        "workspace page source batch ledger is invalid"
                    )
                observed_ids.append(str(binding.get("source_page_id") or ""))
            if sorted(observed_ids) != normalized_ids:
                raise WorkspaceOperationConflict(op_id)
            return result
        finally:
            con.close()

    def bind_page_sources_batch(
        self,
        actor_subject_id: str | None,
        workspace_id: str,
        source_proofs: list[LegacyPageSourceProof],
        *,
        source_revalidator: Callable[[LegacyPageSourceProof], bool],
        base_version: int,
        operation_id: str,
    ) -> dict[str, Any]:
        """Atomically expose one bounded self-owned source subtree.

        All source snapshots are authenticated before the catalog writer lock.
        The handler then inserts any missing rows as pending and activates every
        exact generation in the same catalog transaction, so a subtree is never
        partly visible through the active-binding read boundary.
        """

        if not isinstance(source_proofs, list) or not source_proofs:
            raise ValueError("source_proofs must be a non-empty list")
        if len(source_proofs) > MAX_PAGE_SOURCE_BATCH:
            raise ValueError("source proof batch exceeds limit")
        if not callable(source_revalidator):
            raise ValueError("source_revalidator required")
        normalized: list[
            tuple[LegacyPageSourceProof, str, str, str, str, _AuthorizationRequirement]
        ] = []
        seen: set[tuple[str, str]] = set()
        actor = ""
        ws_id = ""
        authorization: _AuthorizationRequirement | None = None
        for proof in source_proofs:
            (
                current_actor,
                owner,
                current_ws,
                page_id,
                teamspace_id,
                placement,
                current_authorization,
            ) = self._normalize_page_source(
                actor_subject_id, workspace_id, proof, ""
            )
            if current_actor != owner or placement != "private" or teamspace_id:
                raise PermissionError("batch page sources must be self-owned and private")
            if actor and (actor != current_actor or ws_id != current_ws):
                raise ValueError("source proof batch identity mismatch")
            actor = current_actor
            ws_id = current_ws
            authorization = current_authorization
            key = (owner, page_id)
            if key in seen:
                raise ValueError("source proof batch contains a duplicate page")
            seen.add(key)
            normalized.append(
                (
                    proof,
                    owner,
                    page_id,
                    placement,
                    str(proof.content_sha256).lower(),
                    current_authorization,
                )
            )
        assert authorization is not None
        normalized.sort(key=lambda item: (item[1], item[2]))
        workspace_version = _expected_version(base_version)
        op_id = _operation_id(operation_id)
        action = "workspace.page_sources_bound_batch"
        request = {
            "workspace_id": ws_id,
            "base_version": workspace_version,
            "source_proofs": [item[0].descriptor() for item in normalized],
        }
        request_hash = _request_hash(actor, action, request)

        replayed, replay_result = self._replay_from_ledger(
            actor_subject_id=actor,
            operation_id=op_id,
            action=action,
            request_hash=request_hash,
        )
        if replayed:
            replay_con = self._read_connection()
            try:
                self._authorize_requirement(replay_con, actor, authorization)
            finally:
                replay_con.close()
            return replay_result

        def require_candidate(
            con: sqlite3.Connection,
            *,
            require_workspace_version: bool,
        ) -> None:
            self._authorize_requirement(con, actor, authorization)
            if require_workspace_version:
                self._assert_version(con, ws_id, workspace_version)
            for proof, owner, page_id, placement, content_sha256, _auth in normalized:
                row = con.execute(
                    """
                    SELECT * FROM workspace_page_sources
                    WHERE source_owner_subject_id=? AND source_page_id=?
                    """,
                    (owner, page_id),
                ).fetchone()
                if row is None:
                    continue
                if (
                    str(row["workspace_id"]) != ws_id
                    or str(row["state"]) not in {"pending", "active"}
                    or str(row["placement"]) != placement
                    or str(row["teamspace_id"] or "") != ""
                    or str(row["bound_by_subject_id"]) != actor
                    or int(row["source_revision"]) != proof.revision
                    or int(row["source_updated_at"]) != proof.updated_at
                    or str(row["source_sha256"]).lower() != content_sha256
                ):
                    raise ValueError("page source batch binding is stale")

        read_con = self._read_connection()
        try:
            require_candidate(read_con, require_workspace_version=True)
        finally:
            read_con.close()
        for proof, _owner, _page_id, _placement, _sha, _auth in normalized:
            if source_revalidator(proof) is not True:
                raise ValueError("legacy page source proof is invalid or stale")

        def handler(con: sqlite3.Connection) -> _MutationEffect:
            require_candidate(con, require_workspace_version=True)
            workspace_before = self._assert_version(con, ws_id, workspace_version)
            now = _now()
            changed = False
            bindings: list[dict[str, Any]] = []
            for proof, owner, page_id, placement, content_sha256, _auth in normalized:
                row = con.execute(
                    """
                    SELECT * FROM workspace_page_sources
                    WHERE workspace_id=? AND source_owner_subject_id=? AND source_page_id=?
                    """,
                    (ws_id, owner, page_id),
                ).fetchone()
                if row is None:
                    con.execute(
                        """
                        INSERT INTO workspace_page_sources(
                          workspace_id,source_owner_subject_id,source_page_id,
                          teamspace_id,placement,state,quarantined_at,
                          source_revision,source_updated_at,source_sha256,
                          bound_by_subject_id,row_version,created_at,updated_at
                        ) VALUES(?,?,?,NULL,?,'pending',NULL,?,?,?,?,1,?,?)
                        """,
                        (
                            ws_id,
                            owner,
                            page_id,
                            placement,
                            proof.revision,
                            proof.updated_at,
                            content_sha256,
                            actor,
                            now,
                            now,
                        ),
                    )
                    binding_version = 1
                    state = "pending"
                else:
                    binding_version = int(row["row_version"])
                    state = str(row["state"])
                if state == "pending":
                    updated = con.execute(
                        """
                        UPDATE workspace_page_sources
                        SET state='active',quarantined_at=NULL,
                            quarantine_reason=NULL,quarantine_source_generation=NULL,
                            updated_at=?
                        WHERE workspace_id=? AND source_owner_subject_id=?
                          AND source_page_id=? AND state='pending'
                          AND row_version=? AND placement='private'
                          AND teamspace_id IS NULL AND source_revision=?
                          AND source_updated_at=? AND source_sha256=?
                        """,
                        (
                            now,
                            ws_id,
                            owner,
                            page_id,
                            binding_version,
                            proof.revision,
                            proof.updated_at,
                            content_sha256,
                        ),
                    )
                    if updated.rowcount != 1:
                        raise ValueError("page source batch binding is stale")
                    changed = True
                bindings.append(
                    {
                        "workspace_id": ws_id,
                        "source_owner_subject_id": owner,
                        "source_page_id": page_id,
                        "teamspace_id": "",
                        "placement": placement,
                        "state": "active",
                        "source_revision": proof.revision,
                        "source_updated_at": proof.updated_at,
                        "source_sha256": content_sha256,
                        "version": binding_version,
                    }
                )
            workspace = (
                self._bump_workspace(con, ws_id, security_change=True)
                if changed
                else workspace_before
            )
            event = {
                "workspace_id": ws_id,
                "binding_count": len(bindings),
                "bindings": bindings,
            }
            return _MutationEffect(
                result={
                    "workspace": self._workspace_public(workspace),
                    "bindings": bindings,
                    "changed": changed,
                },
                workspace_id=ws_id,
                target_type="legacy_page_source_batch",
                target_id=ws_id,
                event_payload=event,
                authorization=authorization,
            )

        def authorize_replay(con: sqlite3.Connection, _previous: sqlite3.Row) -> None:
            self._authorize_requirement(con, actor, authorization)

        return self._mutate(
            actor_subject_id=actor,
            operation_id=op_id,
            action=action,
            request=request,
            handler=handler,
            replay_authorizer=authorize_replay,
        )

    def quarantine_page_source_if_stale(
        self,
        actor_subject_id: str | None,
        workspace_id: str,
        source_owner_subject_id: str | None,
        source_page_id: str,
        *,
        source_revalidator: Callable[[LegacyPageSourceProof], bool],
        expected_binding_version: int,
        base_version: int,
        operation_id: str,
    ) -> dict[str, Any]:
        """CAS-quarantine an active/pending locator only after trusted revalidation."""
        actor = _subject(actor_subject_id, field="actor_subject_id")
        owner = _subject(
            source_owner_subject_id, field="source_owner_subject_id"
        )
        ws_id = _identifier(workspace_id, prefix="ws", field="workspace_id")
        page_id = str(source_page_id or "").strip()
        if not page_id or len(page_id) > 160:
            raise ValueError("valid source_page_id required")
        if not callable(source_revalidator):
            raise ValueError("source_revalidator required")
        expected = _expected_version(expected_binding_version)
        workspace_version = _expected_version(base_version)
        op_id = _operation_id(operation_id)
        action = "workspace.page_source_quarantined"
        # The idempotency identity is made exclusively from explicit caller
        # input.  Mutable locator proof is deliberately excluded so an exact
        # replay can be resolved after restage or deletion.
        request = {
            "workspace_id": ws_id,
            "source_owner_subject_id": owner,
            "source_page_id": page_id,
            "expected_binding_version": expected,
            "base_version": workspace_version,
        }
        request_hash = _request_hash(actor, action, request)
        replayed, replay_result = self._replay_from_ledger(
            actor_subject_id=actor,
            operation_id=op_id,
            action=action,
            request_hash=request_hash,
        )
        if replayed:
            return replay_result

        read_con = self._read_connection()
        try:
            row = read_con.execute(
                """
                SELECT * FROM workspace_page_sources
                WHERE workspace_id=? AND source_owner_subject_id=? AND source_page_id=?
                """,
                (ws_id, owner, page_id),
            ).fetchone()
            if not row:
                raise ValueError("page source binding is stale")
            ts_id = str(row["teamspace_id"] or "")
            authorization = self._authorization(
                "workspace.page_source.bind_self"
                if actor == owner
                else "workspace.page_source.bind_admin",
                ws_id,
                source_owner_subject_id=owner,
                teamspace_id=ts_id,
            )
            stored_proof = LegacyPageSourceProof(
                actor_subject_id=str(row["bound_by_subject_id"]),
                owner_subject_id=owner,
                page_id=page_id,
                revision=int(row["source_revision"]),
                updated_at=int(row["source_updated_at"]),
                content_sha256=str(row["source_sha256"]),
            )
            if str(row["state"]) not in {"pending", "active"} or int(
                row["row_version"]
            ) != expected:
                raise ValueError("page source binding is stale")
            self._authorize_requirement(read_con, actor, authorization)
            self._assert_version(read_con, ws_id, workspace_version)
        finally:
            read_con.close()
        if source_revalidator(stored_proof) is True:
            return {
                "quarantined": False,
                "workspace_id": ws_id,
                "binding_version": expected,
            }

        def handler(con: sqlite3.Connection) -> _MutationEffect:
            self._authorize_requirement(con, actor, authorization)
            workspace_before = self._assert_version(con, ws_id, workspace_version)
            current = con.execute(
                """
                SELECT state,row_version FROM workspace_page_sources
                WHERE workspace_id=? AND source_owner_subject_id=? AND source_page_id=?
                """,
                (ws_id, owner, page_id),
            ).fetchone()
            if not current or str(current["state"]) not in {"pending", "active"} or int(
                current["row_version"]
            ) != expected:
                raise ValueError("page source binding is stale")
            now = _now()
            con.execute(
                """
                UPDATE workspace_page_sources
                SET state='quarantined',quarantined_at=?,row_version=row_version+1,
                    quarantine_reason='manual',
                    quarantine_source_generation=row_version+1,updated_at=?
                WHERE workspace_id=? AND source_owner_subject_id=? AND source_page_id=?
                  AND row_version=? AND state IN ('pending','active')
                """,
                (now, now, ws_id, owner, page_id, expected),
            )
            workspace = (
                self._bump_workspace(con, ws_id, security_change=True)
                if str(current["state"]) == "active"
                else workspace_before
            )
            event = {
                "source_owner_subject_id": owner,
                "source_page_id": page_id,
                "previous_state": str(current["state"]),
                "version": expected + 1,
                "reason": "legacy_source_stale",
            }
            return _MutationEffect(
                result={
                    "workspace": self._workspace_public(workspace),
                    "quarantined": True,
                    "binding": event,
                },
                workspace_id=ws_id,
                target_type="legacy_page_source",
                target_id=f"{owner}:{page_id}",
                event_payload=event,
                authorization=authorization,
            )

        def authorize_replay(con: sqlite3.Connection, _previous: sqlite3.Row) -> None:
            self._authorize_requirement(con, actor, authorization)

        return self._mutate(
            actor_subject_id=actor,
            operation_id=op_id,
            action=action,
            request=request,
            handler=handler,
            replay_authorizer=authorize_replay,
        )

    def bind_page_source(
        self,
        actor_subject_id: str | None,
        workspace_id: str,
        source_proof: LegacyPageSourceProof,
        *,
        source_revalidator: Callable[[LegacyPageSourceProof], bool],
        teamspace_id: str = "",
        base_version: int,
        operation_id: str,
    ) -> dict[str, Any]:
        """Compatibility wrapper for pending -> revalidate -> CAS activation."""
        stage = self.stage_page_source_binding(
            actor_subject_id,
            workspace_id,
            source_proof,
            teamspace_id=teamspace_id,
            base_version=base_version,
            operation_id=self._derived_operation_id("page-source-stage", operation_id),
        )
        return self.activate_page_source_binding(
            actor_subject_id,
            workspace_id,
            source_proof,
            source_revalidator=source_revalidator,
            expected_binding_version=int(stage["binding"]["version"]),
            teamspace_id=teamspace_id,
            base_version=int(stage["workspace"]["version"]),
            operation_id=operation_id,
        )

    @staticmethod
    def _delivery_transition_result(row: sqlite3.Row) -> dict[str, Any]:
        return {
            "outbox_id": str(row["outbox_id"]),
            "consumer": str(row["consumer"]),
            "status": str(row["status"]),
            "attempt_count": int(row["attempt_count"]),
            "available_at": int(row["available_at"]),
            "row_version": int(row["row_version"]),
            "delivered_at": int(row["delivered_at"]) if row["delivered_at"] is not None else None,
            "dead_lettered_at": int(row["dead_lettered_at"]) if row["dead_lettered_at"] is not None else None,
            "last_error_code": str(row["last_error_code"]) if row["last_error_code"] is not None else None,
        }

    @staticmethod
    def _delivery_time(value: int | None) -> int:
        if value is None:
            return _now()
        # Leave room for the largest permitted lease/backoff addition so the
        # API fails with a stable validation error instead of a driver-specific
        # SQLite integer overflow.
        return _bounded_integer(
            value,
            field="now",
            minimum=0,
            maximum=2**63 - 1 - max(
                MAX_OUTBOX_LEASE_SECONDS, MAX_OUTBOX_BACKOFF_SECONDS
            ),
        )

    def claim_pending_outbox(
        self, consumer: str | None, worker: str | None, *,
        limit: int = MAX_OUTBOX_CLAIM_LIMIT, now: int | None = None,
        lease_seconds: int = 60,
        max_attempts: int = DEFAULT_MAX_OUTBOX_ATTEMPTS,
    ) -> list[dict[str, Any]]:
        """Claim a bounded deterministic batch without mutating parent events."""
        consumer_id = _delivery_principal(consumer, field="consumer")
        worker_id = _delivery_principal(worker, field="worker")
        claim_limit = _bounded_integer(limit, field="limit", minimum=1, maximum=MAX_OUTBOX_CLAIM_LIMIT)
        lease_duration = _bounded_integer(lease_seconds, field="lease_seconds", minimum=1, maximum=MAX_OUTBOX_LEASE_SECONDS)
        attempt_limit = _bounded_integer(max_attempts, field="max_attempts", minimum=1, maximum=MAX_OUTBOX_ATTEMPTS)
        current_time = self._delivery_time(now)
        con = self._write_connection()
        try:
            con.execute("BEGIN IMMEDIATE")
            candidates = con.execute(
                _OUTBOX_CLAIM_CANDIDATES_SQL,
                (consumer_id, current_time, current_time, claim_limit),
            ).fetchall()
            claimed: list[dict[str, Any]] = []
            for candidate in candidates:
                outbox_id = str(candidate["outbox_id"])
                if candidate["status"] is None:
                    con.execute(
                        """INSERT INTO workspace_outbox_deliveries(
                             outbox_id,consumer,status,attempt_count,available_at,
                             row_version,created_at,updated_at
                           ) VALUES(?,?,'pending',0,?,1,?,?)""",
                        (outbox_id, consumer_id, current_time, current_time, current_time),
                    )
                    status, attempt_count, row_version = "pending", 0, 1
                else:
                    status = str(candidate["status"])
                    attempt_count = int(candidate["attempt_count"])
                    row_version = int(candidate["row_version"])
                if status == "retry" and attempt_count >= attempt_limit:
                    updated = con.execute(
                        """UPDATE workspace_outbox_deliveries
                           SET status='dead_letter',last_error_code='max_attempts',
                               last_transition='dead_letter',row_version=row_version+1,
                               updated_at=?,dead_lettered_at=?
                           WHERE outbox_id=? AND consumer=? AND status='retry'
                             AND row_version=? AND available_at<=?""",
                        (current_time, current_time, outbox_id, consumer_id,
                         row_version, current_time),
                    )
                    if updated.rowcount != 1:
                        raise WorkspaceOutboxLeaseConflict("outbox lease unavailable")
                    continue
                if status == "leased" and attempt_count >= attempt_limit:
                    updated = con.execute(
                        """UPDATE workspace_outbox_deliveries
                           SET status='dead_letter',lease_worker=NULL,lease_token=NULL,
                               lease_expires_at=NULL,last_error_code='max_attempts',
                               last_lease_token=?,last_worker=?,last_transition='dead_letter',
                               row_version=row_version+1,updated_at=?,dead_lettered_at=?
                           WHERE outbox_id=? AND consumer=? AND status='leased'
                             AND row_version=? AND lease_expires_at<=?""",
                        (str(candidate["lease_token"]), str(candidate["lease_worker"]),
                         current_time, current_time, outbox_id, consumer_id,
                         row_version, current_time),
                    )
                    if updated.rowcount != 1:
                        raise WorkspaceOutboxLeaseConflict("outbox lease unavailable")
                    continue
                token = _new_id("wlease")
                updated = con.execute(
                    """UPDATE workspace_outbox_deliveries
                       SET status='leased',attempt_count=attempt_count+1,
                           lease_worker=?,lease_token=?,lease_expires_at=?,
                           row_version=row_version+1,updated_at=?
                       WHERE outbox_id=? AND consumer=? AND row_version=? AND (
                         (status IN ('pending','retry') AND available_at<=?) OR
                         (status='leased' AND lease_expires_at<=?)
                       )""",
                    (worker_id, token, current_time + lease_duration, current_time,
                     outbox_id, consumer_id, row_version, current_time, current_time),
                )
                if updated.rowcount != 1:
                    raise WorkspaceOutboxLeaseConflict("outbox lease unavailable")
                claimed.append({
                    "outbox_id": outbox_id,
                    "workspace_id": str(candidate["workspace_id"]),
                    "actor_subject_id": str(candidate["actor_subject_id"]),
                    "event_type": str(candidate["event_type"]),
                    "aggregate_type": str(candidate["aggregate_type"]),
                    "aggregate_id": str(candidate["aggregate_id"]),
                    "payload_json": str(candidate["payload_json"]),
                    "created_at": int(candidate["event_created_at"]),
                    "consumer": consumer_id,
                    "status": "leased",
                    "attempt_count": attempt_count + 1,
                    "available_at": current_time,
                    "lease_token": token,
                    "lease_expires_at": current_time + lease_duration,
                    "row_version": row_version + 1,
                })
            con.commit()
            return claimed
        except Exception:
            con.rollback()
            raise
        finally:
            con.close()

    def _leased_delivery_transition(
        self, *, consumer: str | None, worker: str | None,
        lease_token: str | None, transition: str, now: int | None,
        error_code: str = "", backoff_seconds: int = 0,
        max_attempts: int = DEFAULT_MAX_OUTBOX_ATTEMPTS,
    ) -> dict[str, Any]:
        consumer_id = _delivery_principal(consumer, field="consumer")
        worker_id = _delivery_principal(worker, field="worker")
        token = _lease_token(lease_token)
        current_time = self._delivery_time(now)
        if transition not in {"retry", "delivered", "dead_letter"}:
            raise ValueError("valid delivery transition required")
        code = _delivery_error_code(error_code) if transition != "delivered" else ""
        delay = _bounded_integer(backoff_seconds, field="backoff_seconds", minimum=1, maximum=MAX_OUTBOX_BACKOFF_SECONDS) if transition == "retry" else 0
        attempt_limit = _bounded_integer(max_attempts, field="max_attempts", minimum=1, maximum=MAX_OUTBOX_ATTEMPTS)
        con = self._write_connection()
        try:
            con.execute("BEGIN IMMEDIATE")
            row = con.execute(
                """SELECT * FROM workspace_outbox_deliveries
                   WHERE consumer=? AND (
                     (lease_token=? AND lease_worker=?) OR
                     (last_lease_token=? AND last_worker=?))
                   ORDER BY CASE WHEN lease_token=? THEN 0 ELSE 1 END LIMIT 1""",
                (consumer_id, token, worker_id, token, worker_id, token),
            ).fetchone()
            if not row:
                raise WorkspaceOutboxLeaseConflict("outbox lease unavailable")
            replay_transitions = {transition, "dead_letter"} if transition == "retry" else {transition}
            if (str(row["last_lease_token"] or "") == token
                    and str(row["last_worker"] or "") == worker_id
                    and str(row["last_transition"] or "") in replay_transitions
                    and str(row["status"]) == str(row["last_transition"])):
                con.rollback()
                return self._delivery_transition_result(row)
            if (str(row["status"]) != "leased"
                    or str(row["lease_token"] or "") != token
                    or str(row["lease_worker"] or "") != worker_id
                    or int(row["lease_expires_at"]) <= current_time):
                raise WorkspaceOutboxLeaseConflict("outbox lease unavailable")
            target = "dead_letter" if transition == "retry" and int(row["attempt_count"]) >= attempt_limit else transition
            available_at = current_time + delay if target == "retry" else int(row["available_at"])
            last_error = code if target != "delivered" else row["last_error_code"]
            updated = con.execute(
                """UPDATE workspace_outbox_deliveries
                   SET status=?,available_at=?,lease_worker=NULL,lease_token=NULL,
                       lease_expires_at=NULL,last_error_code=?,last_lease_token=?,
                       last_worker=?,last_transition=?,row_version=row_version+1,
                       updated_at=?,delivered_at=?,dead_lettered_at=?
                   WHERE outbox_id=? AND consumer=? AND status='leased'
                     AND lease_token=? AND lease_worker=? AND row_version=?
                     AND lease_expires_at>?""",
                (target, available_at, last_error, token, worker_id, target,
                 current_time, current_time if target == "delivered" else None,
                 current_time if target == "dead_letter" else None,
                 str(row["outbox_id"]), consumer_id, token, worker_id,
                 int(row["row_version"]), current_time),
            )
            if updated.rowcount != 1:
                raise WorkspaceOutboxLeaseConflict("outbox lease unavailable")
            result = con.execute(
                "SELECT * FROM workspace_outbox_deliveries WHERE outbox_id=? AND consumer=?",
                (str(row["outbox_id"]), consumer_id),
            ).fetchone()
            con.commit()
            return self._delivery_transition_result(result)
        except Exception:
            con.rollback()
            raise
        finally:
            con.close()

    def ack_outbox_delivery(
        self, consumer: str | None, worker: str | None,
        lease_token: str | None, *, now: int | None = None,
    ) -> dict[str, Any]:
        return self._leased_delivery_transition(
            consumer=consumer, worker=worker, lease_token=lease_token,
            transition="delivered", now=now,
        )

    def retry_outbox_delivery(
        self, consumer: str | None, worker: str | None,
        lease_token: str | None, error_code: str | None, *,
        now: int | None = None, backoff_seconds: int = 1,
        max_attempts: int = DEFAULT_MAX_OUTBOX_ATTEMPTS,
    ) -> dict[str, Any]:
        return self._leased_delivery_transition(
            consumer=consumer, worker=worker, lease_token=lease_token,
            transition="retry", now=now, error_code=str(error_code or ""),
            backoff_seconds=backoff_seconds, max_attempts=max_attempts,
        )

    def dead_letter_outbox_delivery(
        self, consumer: str | None, worker: str | None,
        lease_token: str | None, error_code: str | None, *,
        now: int | None = None,
    ) -> dict[str, Any]:
        return self._leased_delivery_transition(
            consumer=consumer, worker=worker, lease_token=lease_token,
            transition="dead_letter", now=now, error_code=str(error_code or ""),
        )

    def audit_counts(self) -> dict[str, int]:
        """Test/operations inspection that does not expose payload content."""
        if not self.exists():
            return {"operations": 0, "audit_events": 0, "outbox_events": 0}
        con = self._read_connection()
        try:
            return {
                "operations": int(con.execute("SELECT COUNT(*) FROM workspace_operations").fetchone()[0]),
                "audit_events": int(con.execute("SELECT COUNT(*) FROM workspace_audit_events").fetchone()[0]),
                "outbox_events": int(con.execute("SELECT COUNT(*) FROM workspace_outbox").fetchone()[0]),
            }
        finally:
            con.close()
